INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6e6a4e7a-abdf-5986-8e9e-058a55348439', '001b1037-df80-5222-9002-805487fbfde4', NULL, 'Михаил Р.', 'COUPLE', 9.0, '2025-05-01', 'Отдых мечты', 'Галька мелкая и чистая, море без мути даже после ветра. Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '+чистота', '+тишина', '-цены'], '2025-05-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9b1ca36a-9351-54eb-84a1-4d46eb9ed82a', '001b1037-df80-5222-9002-805487fbfde4', NULL, 'Евгений Ч.', 'FRIENDS', 8.5, '2025-05-01', 'Рекомендую, но с оговорками', 'Мелкая галька, вода прозрачная — видно дно. Тихо, ночью ничего не слышно — отлично выспались.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+тишина', '-ремонт'], '2025-05-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5127f099-a720-535d-afad-9f78233f854c', '001b1037-df80-5222-9002-805487fbfde4', NULL, 'Роман О.', 'COUPLE', 8.5, '2025-08-01', 'Достойно за свои деньги', 'Галька мелкая и чистая, море без мути даже после ветра. Завтраки вкусные, кофе нормальный, а не из автомата.', 'В августе у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-медузы', '+еда'], '2025-08-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('526c104f-7365-53cc-9088-94d13394a72f', '001b1037-df80-5222-9002-805487fbfde4', NULL, 'Ирина Г.', 'COUPLE', 9.0, '2025-08-01', 'Отдых мечты', 'Мелкая галька, вода прозрачная — видно дно. СПА отличное, массаж — лучший за поездку. Персонал приветливый, любые вопросы решали быстро.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+СПА', '-ремонт', '+персонал'], '2025-09-08T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('96e43604-d79c-5213-8b02-954073134aea', '001b1037-df80-5222-9002-805487fbfde4', NULL, 'Полина П.', 'COUPLE', 9.5, '2025-07-01', 'Вернёмся ещё!', 'Мелкая галька, вода прозрачная — видно дно. СПА отличное, массаж — лучший за поездку. Номер убирали каждый день, бельё меняли без напоминаний. Тихо, ночью ничего не слышно — отлично выспались. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+пляж', '+СПА', '+чистота', '+тишина', '+персонал'], '2025-08-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('3b063fee-c76f-5969-8b6c-b27bbd830ba6', '0071d0eb-1306-571a-945c-c4ff69811f0f', NULL, 'Юлия К.', 'FAMILY', 8.5, '2026-09-01', 'Достойно за свои деньги', 'Завтраки вкусные, кофе нормальный, а не из автомата. Везде чисто — и в номере, и у бассейна. Расположение супер: всё главное — пешком.', 'После прогулки по лесу сняли клеща — берите спрей и закрытую одежду.', ARRAY['-клещи', '+еда', '+чистота', '+расположение'], '2026-09-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a22b0d0c-2965-54be-b2bf-ecbe75ff9aac', '0071d0eb-1306-571a-945c-c4ff69811f0f', NULL, 'Никита Я.', 'BUSINESS', 8.0, '2026-01-01', 'В целом всё отлично', 'Очень спокойно, слышно только птиц и море. Расположение супер: всё главное — пешком.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+тишина', '+расположение', '-ремонт'], '2026-01-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('513bd9b2-49bd-5189-8586-bd1c9b0db51d', '0071d0eb-1306-571a-945c-c4ff69811f0f', NULL, 'Арман Я.', 'BUSINESS', 8.0, '2025-09-01', 'Хороший отдых', 'Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', 'После прогулки по лесу сняли клеща — берите спрей и закрытую одежду.', ARRAY['-клещи', '+чистота', '+тишина', '+расположение', '+персонал'], '2025-09-25T12:00:00+03:00');
