INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('183a7aa4-debd-50ff-b20e-a5aa4e8e1123', '03fc52ae-ddba-50b8-89fd-edb252b91759', NULL, 'Екатерина П.', 'BUSINESS', 7.0, '2025-06-01', 'На один раз', 'Расположение супер: всё главное — пешком.', 'Вечером комары — без репеллента никуда. Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['-комары', '-уборка', '+расположение'], '2025-06-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4a224a20-2dae-552e-b88d-77538f642de7', '03fc52ae-ddba-50b8-89fd-edb252b91759', NULL, 'Людмила Ч.', 'FAMILY', 7.5, '2025-10-01', 'Достойно за свои деньги', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Расположение супер: всё главное — пешком.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+еда', '-уборка', '+расположение'], '2025-10-30T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8a8f1385-2052-5f73-ad64-f708cc46064e', '04e30a13-aff3-501b-b2df-af157bab37c1', NULL, 'Евгений Ф.', 'FAMILY', 9.0, '2025-01-01', 'Всё понравилось', 'Пляж Ао Нанг рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Взяли маски — у камней полно рыбы. Номер убирали каждый день, бельё меняли без напоминаний. На ресепшене помогли с экскурсиями и такси.', 'Отливы сильные: после обеда вода уходит далеко, с ребёнком купались только утром.', ARRAY['+пляж', '+детям', '-отливы', '+снорклинг', '+чистота', '+персонал'], '2025-02-06T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1b91634e-b6ca-512f-abf3-3133cef0995e', '04e30a13-aff3-501b-b2df-af157bab37c1', NULL, 'Людмила Г.', 'SENIORS', 7.5, '2025-12-01', 'Рекомендую, но с оговорками', 'Пляж Ао Нанг рядом — песок чистый, лежаки бесплатные. Взяли маски — у камней полно рыбы.', 'Отливы сильные: после обеда вода уходит далеко, купались только в прилив.', ARRAY['+пляж', '-отливы', '+снорклинг'], '2025-12-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('0337d903-db7e-57ab-9616-0c9bc2597bc2', '04e30a13-aff3-501b-b2df-af157bab37c1', NULL, 'Нурлан Я.', 'SOLO', 8.5, '2025-01-01', 'Хороший отдых', 'Пляж Ао Нанг рядом — песок чистый, лежаки бесплатные. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна.', 'Смотрите таблицу приливов! В отлив по колено на сотню метров, плавать нельзя.', ARRAY['+пляж', '-отливы', '+снорклинг', '+еда', '+чистота'], '2025-01-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('df1cc9ad-a0e1-5f18-94be-c730a70dea1e', '04e30a13-aff3-501b-b2df-af157bab37c1', NULL, 'Ольга Т.', 'COUPLE', 8.5, '2025-12-01', 'В целом всё отлично', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. На завтрак местная кухня — пробовали каждый день что-то новое. Номер убирали каждый день, бельё меняли без напоминаний.', 'Смотрите таблицу приливов! В отлив по колено на сотню метров, плавать нельзя.', ARRAY['+пляж', '-отливы', '+еда', '+чистота'], '2025-12-31T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('0db870e6-9478-526a-817a-ca63e45b0514', '06521dfa-a86b-58dd-9d60-36b53d6f526c', NULL, 'Владимир Д.', 'COUPLE', 8.0, '2026-08-01', 'Хороший отдых', 'Галька мелкая и чистая, море без мути даже после ветра. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Очень спокойно, слышно только птиц и море. На ресепшене помогли с экскурсиями и такси.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. Вода холоднее, чем ждали: зашёл — и сразу обратно. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-толпы', '-холодная вода', '+еда', '+тишина', '-рельеф', '+персонал'], '2026-08-27T12:00:00+03:00');
