INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('534b61b9-3b6a-5545-8ac7-05be4e5bcebd', '0bc59243-5efa-5568-ab86-499fdc809c4a', NULL, 'Дарья Л.', 'SOLO', 8.0, '2026-05-01', 'Рекомендую, но с оговорками', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Везде чисто — и в номере, и у бассейна. Расположение супер: всё главное — пешком.', 'Ремонт в номере местами староват.', ARRAY['+еда', '+чистота', '+расположение', '-ремонт'], '2026-05-16T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ff68507c-ebb8-5804-ae02-743394a146d4', '0bc59243-5efa-5568-ab86-499fdc809c4a', NULL, 'Ирина Т.', 'COUPLE', 8.5, '2025-05-01', 'В целом всё отлично', 'Завтраки вкусные, кофе нормальный, а не из автомата. Чистота идеальная, придраться не к чему. Центр рядом, гуляли пешком целыми днями.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+еда', '+чистота', '-Wi-Fi', '+расположение'], '2025-05-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7c5c1168-c901-5620-b328-22dda51be529', '0bd0ea8d-58d5-53b6-a45f-3359fd8c1654', NULL, 'Дарья У.', 'COUPLE', 7.5, '2026-06-01', 'Рекомендую, но с оговорками', 'Море прозрачное, как в бассейне. Завтраки вкусные, кофе нормальный, а не из автомата. Чистота идеальная, придраться не к чему. Хорошая шумоизоляция, спали с открытым балконом.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '+чистота', '+тишина', '-рельеф'], '2026-07-09T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8b94a132-2e16-54c0-964b-f0ca480ad5f1', '0bd0ea8d-58d5-53b6-a45f-3359fd8c1654', NULL, 'Ольга Х.', 'FAMILY', 7.0, '2026-09-01', 'Есть над чем поработать', 'Море прозрачное, как в бассейне. Завтраки вкусные, кофе нормальный, а не из автомата.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В сентябре у берега было много медуз, пару дней купались только в бассейне. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '-медузы', '+еда', '-рельеф'], '2026-10-02T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('295f181a-7644-51af-9018-0dd1b89a1574', '0bd0ea8d-58d5-53b6-a45f-3359fd8c1654', NULL, 'Татьяна Л.', 'SENIORS', 6.5, '2026-07-01', 'Ожидали большего', 'Море прозрачное, как в бассейне. Номер убирали каждый день, бельё меняли без напоминаний.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В разгар сезона на пляже тесно, лежаки занимают с утра. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару. Лифта нет — с чемоданами и пожилыми родителями тяжело.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '+чистота', '-рельеф', '-нет лифта'], '2026-08-06T12:00:00+03:00');
