INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('78f214e7-41e1-597d-95d8-be18ed3e7f7a', '0c96f7b7-b6b4-5806-bcb7-ba3cda36f575', NULL, 'Айгерим С.', 'COUPLE', 8.0, '2025-08-01', 'Достойно за свои деньги', 'Мелкая галька, вода прозрачная — видно дно. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Персонал приветливый, любые вопросы решали быстро.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. В августе у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-толпы', '-медузы', '+еда', '+персонал'], '2025-08-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('26f3d4da-987c-58b9-9564-33a22d5ba6d4', '0c96f7b7-b6b4-5806-bcb7-ba3cda36f575', NULL, 'Анна Ж.', 'FRIENDS', 7.5, '2026-09-01', 'В целом всё отлично', 'Галька мелкая и чистая, море без мути даже после ветра. Ужины вкусные, есть детское меню.', 'В сентябре у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-медузы', '+еда'], '2026-10-03T12:00:00+03:00');
