INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('457166c9-f9c9-5bbc-8b89-941a5b54041c', '0cab6946-9d09-56d1-98a8-9158b770ae8e', NULL, 'Сергей И.', 'SENIORS', 7.5, '2026-08-01', 'Рекомендую, но с оговорками', 'Мелкая галька, вода прозрачная — видно дно. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Везде чисто — и в номере, и у бассейна.', 'Слышимость хорошая — соседей слышно, берите беруши. Лифта нет — с чемоданами и пожилыми родителями тяжело.', ARRAY['+пляж', '+еда', '+чистота', '-шум', '-нет лифта'], '2026-09-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('b6125a45-809f-5413-95b1-a42a8d4a9f6a', '0d19522c-1e82-51d6-a42c-6970ffb9712d', NULL, 'Алексей Н.', 'FAMILY', 9.5, '2025-11-01', 'Всё понравилось', 'Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком.', 'Ремонт в номере местами староват.', ARRAY['+чистота', '+тишина', '+расположение', '-ремонт'], '2025-11-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5a98331c-9f7d-508f-a600-420b2e2a34fb', '0d19522c-1e82-51d6-a42c-6970ffb9712d', NULL, 'Дарья Т.', 'FAMILY', 9.0, '2025-11-01', 'Лучший отпуск за последние годы', 'Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+чистота', '+тишина', '-Wi-Fi', '+расположение'], '2025-11-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('09c0c1ac-0c00-57ab-a25d-6c1a683b9dd1', '0d19522c-1e82-51d6-a42c-6970ffb9712d', NULL, 'Ксения Г.', 'COUPLE', 9.0, '2025-10-01', 'Всё понравилось', 'На завтрак местная кухня — пробовали каждый день что-то новое. Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+еда', '+чистота', '+тишина', '-Wi-Fi', '+расположение', '+персонал'], '2025-11-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('98d802fb-0fed-5bb0-8894-cee6b3a805e5', '0d19522c-1e82-51d6-a42c-6970ffb9712d', NULL, 'Иван Ч.', 'SENIORS', 9.5, '2025-11-01', 'Лучший отпуск за последние годы', 'СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна. Тихо, ночью ничего не слышно — отлично выспались. Центр рядом, гуляли пешком целыми днями. Ездили с мамой на коляске: пандусы, лифт, в номере поручни и душ без поддона. Персонал приветливый, любые вопросы решали быстро.', 'Ремонт в номере местами староват.', ARRAY['+СПА', '+еда', '+чистота', '+тишина', '+расположение', '+доступность', '-ремонт', '+персонал'], '2025-12-10T12:00:00+03:00');
