INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('148c2dbc-3818-551c-81a4-9c5e5b68b1a2', '15b6d7e9-59ae-5816-8439-18676611d4be', NULL, 'Игорь Ч.', 'SENIORS', 9.0, '2026-02-01', 'Всё понравилось', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Хорошая шумоизоляция, спали с открытым балконом.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '+еда', '+тишина', '-рельеф'], '2026-03-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8213f1fd-1ba8-580e-b2b0-017fa6efa489', '15b6d7e9-59ae-5816-8439-18676611d4be', NULL, 'Евгений Б.', 'SOLO', 10.0, '2026-01-01', 'Вернёмся ещё!', 'Песок мягкий, вода прозрачная, к морю пара минут. Хорошая шумоизоляция, спали с открытым балконом. Wi-Fi быстрый, без проблем работал из номера.', NULL, ARRAY['+пляж', '+тишина', '+Wi-Fi'], '2026-02-04T12:00:00+03:00');
