INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e41af608-77a6-5f5c-8edc-e7cce620379a', '15b6d7e9-59ae-5816-8439-18676611d4be', NULL, 'Алексей Л.', 'COUPLE', 8.5, '2026-02-01', 'Рекомендую, но с оговорками', 'Песок мягкий, вода прозрачная, к морю пара минут. Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. На ресепшене помогли с экскурсиями и такси.', 'Цены в баре и ресторане кусаются.', ARRAY['+пляж', '+чистота', '+тишина', '-цены', '+персонал'], '2026-02-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('206e6c20-e2f7-502a-a93c-69bf3686c70d', '15b6d7e9-59ae-5816-8439-18676611d4be', NULL, 'Светлана С.', 'COUPLE', 9.5, '2025-01-01', 'Отдых мечты', 'Песок мягкий, вода прозрачная, к морю пара минут. Завтраки вкусные, кофе нормальный, а не из автомата. Очень спокойно, слышно только птиц и море. Персонал приветливый, любые вопросы решали быстро.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '+еда', '+тишина', '-рельеф', '+персонал'], '2025-01-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('46aa3097-015a-5072-a8be-875740da91ce', '160b4dba-331d-5adf-8cbc-2962929ffd16', NULL, 'Олег Ч.', 'FAMILY', 8.5, '2026-03-01', 'Рекомендую, но с оговорками', 'Номер убирали каждый день, бельё меняли без напоминаний. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+чистота', '+тишина', '+расположение', '-цены', '+персонал'], '2026-03-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4137fd93-87e0-5663-bba4-b563e95e0f1d', '160b4dba-331d-5adf-8cbc-2962929ffd16', NULL, 'Никита З.', 'COUPLE', 8.0, '2026-06-01', 'Рекомендую, но с оговорками', 'Расположение супер: всё главное — пешком.', NULL, ARRAY['+расположение'], '2026-07-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('419873cf-9c3a-53a3-ae7d-1767674e232e', '160b4dba-331d-5adf-8cbc-2962929ffd16', NULL, 'Наталья П.', 'FAMILY', 9.0, '2025-05-01', 'Всё понравилось', 'На завтрак местная кухня — пробовали каждый день что-то новое. Тихо, ночью ничего не слышно — отлично выспались. Центр рядом, гуляли пешком целыми днями.', NULL, ARRAY['+еда', '+тишина', '+расположение'], '2025-06-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9cecf840-c31d-515f-a986-b6b77833ede0', '160b4dba-331d-5adf-8cbc-2962929ffd16', NULL, 'Иван В.', 'COUPLE', 8.0, '2026-05-01', 'Рекомендую, но с оговорками', 'Чистота идеальная, придраться не к чему. Хорошая шумоизоляция, спали с открытым балконом. Центр рядом, гуляли пешком целыми днями.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+чистота', '+тишина', '+расположение', '-ремонт'], '2026-06-01T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('98b15e89-a444-57e0-bef4-e3fac8f5f2be', '16cbc9b3-32c9-52ac-b3d0-092b2d0468f3', NULL, 'Дарья А.', 'COUPLE', 9.5, '2025-02-01', 'Лучший отпуск за последние годы', 'Пляж Ката рядом — песок чистый, лежаки бесплатные. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Серф-школа у пляжа, за неделю встал на доску. На завтрак местная кухня — пробовали каждый день что-то новое. Номер убирали каждый день, бельё меняли без напоминаний. Хорошая шумоизоляция, спали с открытым балконом.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+снорклинг', '+серфинг', '+еда', '+чистота', '+тишина', '-ремонт'], '2025-03-08T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ff339b09-abbc-56de-9082-d75e242de395', '16cbc9b3-32c9-52ac-b3d0-092b2d0468f3', NULL, 'Павел Л.', 'COUPLE', 9.0, '2026-01-01', 'Лучший отпуск за последние годы', 'Пляж Ката рядом — песок чистый, лежаки бесплатные. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Серф-школа у пляжа, за неделю встал на доску. Завтраки вкусные, кофе нормальный, а не из автомата. Номер убирали каждый день, бельё меняли без напоминаний.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+снорклинг', '+серфинг', '+еда', '+чистота', '-ремонт'], '2026-02-11T12:00:00+03:00');
