INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('cf727d46-626b-50fe-9411-44552f141756', '177e1c24-3fbd-5980-9b18-b8cc21977ea7', NULL, 'Ольга Т.', 'SENIORS', 9.5, '2025-09-01', 'Всё понравилось', 'Песок мягкий, вода прозрачная, к морю пара минут. Ужины вкусные, есть детское меню. Номер убирали каждый день, бельё меняли без напоминаний. Ездили с мамой на коляске: пандусы, лифт, в номере поручни и душ без поддона.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '+еда', '+чистота', '+доступность', '-цены'], '2025-09-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a45a4680-74c1-5da5-8c01-6e33a139a319', '177e1c24-3fbd-5980-9b18-b8cc21977ea7', NULL, 'Ирина В.', 'FRIENDS', 9.5, '2025-07-01', 'Всё понравилось', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Везде чисто — и в номере, и у бассейна. На ресепшене помогли с экскурсиями и такси.', 'Жара была под 40, днём из номера почти не выходили. В июле у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-жара', '-медузы', '+СПА', '+еда', '+чистота', '+персонал'], '2025-08-06T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('72fd95c8-bcfe-55a4-8d3c-56f836326c51', '177e1c24-3fbd-5980-9b18-b8cc21977ea7', NULL, 'Ксения В.', 'FAMILY', 10.0, '2025-10-01', 'Лучший отпуск за последние годы', 'Песок мягкий, вода прозрачная, к морю пара минут. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера. Ужины вкусные, есть детское меню. Везде чисто — и в номере, и у бассейна. На ресепшене помогли с экскурсиями и такси.', 'Цены в баре и ресторане кусаются.', ARRAY['+пляж', '+детям', '+аквапарк', '+еда', '+чистота', '-цены', '+персонал'], '2025-10-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7170b9da-97cd-5fc2-8f4b-1cbb0bfaa47d', '177e1c24-3fbd-5980-9b18-b8cc21977ea7', NULL, 'Ксения Е.', 'FAMILY', 9.5, '2026-03-01', 'Вернёмся ещё!', 'Пляж Белека рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Номер убирали каждый день, бельё меняли без напоминаний.', NULL, ARRAY['+пляж', '+детям', '+аквапарк', '+СПА', '+еда', '+чистота'], '2026-03-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4e4c2561-98ad-5061-972d-bd4a2dda979f', '177e1c24-3fbd-5980-9b18-b8cc21977ea7', NULL, 'Людмила Р.', 'SOLO', 9.0, '2026-06-01', 'Всё понравилось', 'Пляж Белека рядом — песок чистый, лежаки бесплатные. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Wi-Fi быстрый, без проблем работал из номера. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+пляж', '+еда', '+Wi-Fi', '+персонал'], '2026-07-02T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d4a5969a-248c-5ad5-ba9b-3eab14bf6e70', '19ecb6e6-2a82-5af4-b7cf-dd77d44a7651', NULL, 'Павел Ж.', 'SOLO', 8.0, '2026-08-01', 'В целом всё отлично', 'Пляж Нуса-Дуа рядом — песок чистый, лежаки бесплатные. СПА отличное, массаж — лучший за поездку. Чистота идеальная, придраться не к чему. Персонал приветливый, любые вопросы решали быстро.', 'Отливы сильные: после обеда вода уходит далеко, купались только в прилив. Несколько дней висели красные флаги, купаться не разрешали.', ARRAY['+пляж', '-отливы', '-волны', '+СПА', '+чистота', '+персонал'], '2026-08-26T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('84be5615-dd2d-5714-8f5e-e4971af9314a', '19ecb6e6-2a82-5af4-b7cf-dd77d44a7651', NULL, 'Арман Л.', 'COUPLE', 8.5, '2026-05-01', 'Достойно за свои деньги', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Тихо, ночью ничего не слышно — отлично выспались. На ресепшене помогли с экскурсиями и такси.', 'Смотрите таблицу приливов! В отлив по колено на сотню метров, плавать нельзя. Несколько дней висели красные флаги, купаться не разрешали.', ARRAY['+пляж', '-отливы', '+снорклинг', '-волны', '+тишина', '+персонал'], '2026-05-31T12:00:00+03:00');
