INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('aa1b8ce0-469b-5944-b96c-54bd670d2398', '19ecb6e6-2a82-5af4-b7cf-dd77d44a7651', NULL, 'Анна Ч.', 'FAMILY', 10.0, '2025-10-01', 'Всё понравилось', 'Песок мягкий, вода прозрачная, к морю пара минут. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Аквапарк — восторг детей, горки работают с утра до вечера. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Везде чисто — и в номере, и у бассейна. Очень спокойно, слышно только птиц и море.', 'Отливы сильные: после обеда вода уходит далеко, с ребёнком купались только утром.', ARRAY['+пляж', '+детям', '-отливы', '+снорклинг', '+аквапарк', '+СПА', '+еда', '+чистота', '+тишина'], '2025-11-10T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1ccf4bc7-4a77-54b9-945c-f7ae6ee5f1da', '19ecb6e6-2a82-5af4-b7cf-dd77d44a7651', NULL, 'Гоар Н.', 'SOLO', 9.0, '2026-05-01', 'Всё понравилось', 'Песок мягкий, вода прозрачная, к морю пара минут. Номер убирали каждый день, бельё меняли без напоминаний. Хорошая шумоизоляция, спали с открытым балконом. Персонал приветливый, любые вопросы решали быстро.', 'Отливы сильные: после обеда вода уходит далеко, купались только в прилив.', ARRAY['+пляж', '-отливы', '+чистота', '+тишина', '+персонал'], '2026-06-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7bce31f7-b01e-5465-870a-321f47ec1e11', '1bc376cb-4c3d-51b6-aca0-fbba60f768ee', NULL, 'Юлия Ч.', 'FRIENDS', 8.0, '2025-07-01', 'В целом всё отлично', 'СПА отличное, массаж — лучший за поездку. Центр рядом, гуляли пешком целыми днями.', 'Уборка так себе: полотенца меняли через раз. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+СПА', '-уборка', '+расположение', '-рельеф'], '2025-07-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8bfd5c3c-4b04-5468-942f-c849d47eb4f8', '1bc376cb-4c3d-51b6-aca0-fbba60f768ee', NULL, 'Галина Л.', 'BUSINESS', 8.0, '2026-07-01', 'Рекомендую, но с оговорками', 'СПА отличное, массаж — лучший за поездку. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями.', 'Пыль под кроватью и на балконе, пришлось просить убрать. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+СПА', '-уборка', '+Wi-Fi', '+расположение', '-рельеф'], '2026-08-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('77571d3e-a772-584d-93d0-9b4a7005ffd5', '1bc376cb-4c3d-51b6-aca0-fbba60f768ee', NULL, 'Ольга И.', 'FRIENDS', 9.0, '2025-09-01', 'Лучший отпуск за последние годы', 'СПА отличное, массаж — лучший за поездку. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Расположение супер: всё главное — пешком.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+СПА', '+еда', '-уборка', '+расположение'], '2025-10-01T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('888bdf92-8ccc-5557-928c-305dff357907', '1bc376cb-4c3d-51b6-aca0-fbba60f768ee', NULL, 'Екатерина С.', 'FRIENDS', 9.0, '2025-08-01', 'Вернёмся ещё!', 'Расположение супер: всё главное — пешком.', NULL, ARRAY['+расположение'], '2025-09-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('775b127e-0052-58d4-b095-57daaac5f836', '1cfbc9dd-d63c-590f-af31-894d19975f5b', NULL, 'Иван И.', 'FRIENDS', 8.0, '2026-04-01', 'Хороший отдых', 'Тёмный вулканический песок — непривычно, но очень красиво на фото. Взяли маски — у камней полно рыбы. Очень спокойно, слышно только птиц и море. На ресепшене помогли с экскурсиями и такси.', 'Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '+снорклинг', '+тишина', '-трансфер', '+персонал'], '2026-05-04T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f39aa5e7-fc98-5cc7-b0a2-ca987623117f', '1cfbc9dd-d63c-590f-af31-894d19975f5b', NULL, 'Наталья Ч.', 'FAMILY', 8.5, '2025-07-01', 'В целом всё отлично', 'Тёмный вулканический песок — непривычно, но очень красиво на фото. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Хорошая шумоизоляция, спали с открытым балконом. На ресепшене помогли с экскурсиями и такси.', 'Несколько дней висели красные флаги, купаться не разрешали. Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '+детям', '+снорклинг', '-волны', '+еда', '+тишина', '-трансфер', '+персонал'], '2025-07-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('697c7cf1-cc54-5a2a-b5fb-531641c84285', '1cfbc9dd-d63c-590f-af31-894d19975f5b', NULL, 'Николай Л.', 'FRIENDS', 8.0, '2025-10-01', 'Хороший отдых', 'Тёмный вулканический песок — непривычно, но очень красиво на фото. Очень спокойно, слышно только птиц и море. На ресепшене помогли с экскурсиями и такси.', 'Несколько дней висели красные флаги, купаться не разрешали.', ARRAY['+пляж', '-волны', '+тишина', '+персонал'], '2025-11-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('785ab283-78b2-5dc9-8385-d0b577280d4a', '1cfbc9dd-d63c-590f-af31-894d19975f5b', NULL, 'Светлана К.', 'COUPLE', 6.5, '2026-04-01', 'Есть над чем поработать', 'Тёмный вулканический песок — непривычно, но очень красиво на фото. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Персонал приветливый, любые вопросы решали быстро.', 'В обед песок раскаляется — без сланцев не дойти до воды. Вечером комары — без репеллента никуда. Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '-горячий песок', '+снорклинг', '-комары', '-трансфер', '+персонал'], '2026-04-26T12:00:00+03:00');
