INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('273de6a6-6988-5619-83b0-53c942c93438', '1e7cb264-5cec-58fe-97dc-2182c5e9df14', NULL, 'Дмитрий З.', 'COUPLE', 8.0, '2025-11-01', 'Рекомендую, но с оговорками', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Номер убирали каждый день, бельё меняли без напоминаний.', 'У рифа морские ежи — без тапочек не заходите.', ARRAY['+пляж', '+снорклинг', '-ежи', '+еда', '+чистота'], '2025-11-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('93a9c694-62f0-5251-85fe-0896ac1b77d1', '21660db6-f43e-590d-a84f-5807bd77e94a', NULL, 'Арман Ж.', 'COUPLE', 7.0, '2025-08-01', 'На один раз', 'Галька мелкая и чистая, море без мути даже после ветра. Ужины вкусные, есть детское меню.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. Уборка так себе: полотенца меняли через раз. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-толпы', '+еда', '-уборка', '-шум'], '2025-08-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('2fe6b613-3ed1-56c7-80a8-fe4cdf35bc4e', '21660db6-f43e-590d-a84f-5807bd77e94a', NULL, 'Наталья Н.', 'FAMILY', 6.0, '2026-08-01', 'Ожидали большего', 'Мелкая галька, вода прозрачная — видно дно. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. На ресепшене помогли с экскурсиями и такси.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. Пыль под кроватью и на балконе, пришлось просить убрать. Слышимость хорошая — соседей слышно, берите беруши.', ARRAY['+пляж', '-толпы', '+еда', '-уборка', '-шум', '+персонал'], '2026-08-19T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('b500af0d-0956-5ef0-888d-6db009b0d614', '21660db6-f43e-590d-a84f-5807bd77e94a', NULL, 'Тимур Р.', 'COUPLE', 6.5, '2026-08-01', 'Ожидали большего', 'Галька мелкая и чистая, море без мути даже после ветра. Ужины вкусные, есть детское меню. Персонал приветливый, любые вопросы решали быстро.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. Пыль под кроватью и на балконе, пришлось просить убрать. Слышимость хорошая — соседей слышно, берите беруши. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-толпы', '+еда', '-уборка', '-шум', '-рельеф', '+персонал'], '2026-08-19T12:00:00+03:00');
