INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('673bc459-024f-5282-b9e5-5c349d75d2e2', '21660db6-f43e-590d-a84f-5807bd77e94a', NULL, 'Айгерим П.', 'FAMILY', 6.0, '2026-08-01', 'На один раз', 'Мелкая галька, вода прозрачная — видно дно. Детский клуб с аниматорами — удалось и самим отдохнуть.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. В августе у берега было много медуз, пару дней купались только в бассейне. Пыль под кроватью и на балконе, пришлось просить убрать. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-толпы', '-медузы', '+детям', '-уборка', '-шум'], '2026-08-28T12:00:00+03:00');
