INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('76c0c29e-3726-56df-88ae-6c4f008424cc', '226bed35-17f2-57f2-8258-28d33888a70c', NULL, 'Владимир Ж.', 'BUSINESS', 9.0, '2025-11-01', 'Отдых мечты', 'Wi-Fi быстрый, без проблем работал из номера. Расположение супер: всё главное — пешком.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+Wi-Fi', '+расположение', '-ремонт'], '2025-12-08T12:00:00+03:00');
