INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('71650467-f59b-5ce8-98f9-4331b7d1eae4', '226bed35-17f2-57f2-8258-28d33888a70c', NULL, 'Светлана Т.', 'FAMILY', 8.5, '2025-03-01', 'Хороший отдых', 'СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое. Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+СПА', '+еда', '+тишина', '+расположение', '-цены'], '2025-04-03T12:00:00+03:00');
