INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f26127ee-e344-5b80-a143-3724cb4f82a2', '22c45f96-54a5-5445-a1ca-9156d06ec075', NULL, 'Татьяна У.', 'COUPLE', 8.5, '2025-05-01', 'В целом всё отлично', 'Завтраки вкусные, кофе нормальный, а не из автомата. Центр рядом, гуляли пешком целыми днями. На ресепшене помогли с экскурсиями и такси.', 'Цены в баре и ресторане кусаются.', ARRAY['+еда', '+расположение', '-цены', '+персонал'], '2025-05-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('31a0a6f6-5370-510b-b324-f5e14ca4fa8f', '22c45f96-54a5-5445-a1ca-9156d06ec075', NULL, 'Виктория Б.', 'SOLO', 8.5, '2026-05-01', 'В целом всё отлично', 'На завтрак местная кухня — пробовали каждый день что-то новое. Очень спокойно, слышно только птиц и море. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями.', 'Ремонт в номере местами староват.', ARRAY['+еда', '+тишина', '+Wi-Fi', '+расположение', '-ремонт'], '2026-05-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7cdf2012-a622-5012-bd00-45731c3175b7', '271e3644-c44c-5b91-874d-77edbe23f231', NULL, 'Евгений И.', 'COUPLE', 6.5, '2026-06-01', 'Ожидали большего', 'Вода кристально чистая, на глубине видно каждый камень. Ужины вкусные, есть детское меню.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '-шум'], '2026-06-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5a62095f-fa4e-567b-9e28-1057b7efbfca', '271e3644-c44c-5b91-874d-77edbe23f231', NULL, 'Виктория Ж.', 'SENIORS', 6.0, '2025-04-01', 'На один раз', 'Вода кристально чистая, на глубине видно каждый камень. Взяли маски — у камней полно рыбы. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Ночью шумно: музыка с улицы до двух часов. Wi-Fi слабый, в номере почти не ловит. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+еда', '-шум', '-Wi-Fi', '-рельеф'], '2025-05-10T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a6d4bdc0-7070-5d16-97fd-ea899fb1bdcd', '271e3644-c44c-5b91-874d-77edbe23f231', NULL, 'Владимир У.', 'COUPLE', 5.0, '2026-07-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. Взяли маски — у камней полно рыбы. Ужины вкусные, есть детское меню.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Жара была под 40, днём из номера почти не выходили. Уборка так себе: полотенца меняли через раз. Слышимость хорошая — соседей слышно, берите беруши. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '-жара', '+еда', '-уборка', '-шум', '-Wi-Fi'], '2026-07-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4fc4db8e-b1ec-5b0b-8441-e2481ed08185', '271e3644-c44c-5b91-874d-77edbe23f231', NULL, 'Сергей У.', 'SOLO', 6.0, '2026-05-01', 'Есть над чем поработать', 'Море прозрачное, как в бассейне. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Персонал приветливый, любые вопросы решали быстро.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Уборка так себе: полотенца меняли через раз. Слышимость хорошая — соседей слышно, берите беруши. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+еда', '-уборка', '-шум', '-Wi-Fi', '+персонал'], '2026-05-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('bc46a7e3-54cf-5302-8a35-3ef26c0d041d', '271e3644-c44c-5b91-874d-77edbe23f231', NULL, 'Андрей П.', 'FAMILY', 6.5, '2025-11-01', 'На один раз', 'Море прозрачное, как в бассейне. Аквапарк — восторг детей, горки работают с утра до вечера. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Уборка так себе: полотенца меняли через раз. Ночью шумно: музыка с улицы до двух часов. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+аквапарк', '+еда', '-уборка', '-шум', '-рельеф'], '2025-12-04T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('886c8d12-42af-5c21-8317-c63f150b708f', '271e3644-c44c-5b91-874d-77edbe23f231', NULL, 'Елена Я.', 'FAMILY', 5.5, '2026-06-01', 'На один раз', 'Море прозрачное, как в бассейне. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Аквапарк — восторг детей, горки работают с утра до вечера. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Уборка так себе: полотенца меняли через раз. Слышимость хорошая — соседей слышно, берите беруши. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+аквапарк', '+еда', '-уборка', '-шум', '-Wi-Fi'], '2026-06-26T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('309f24d6-a9ba-5c61-b6ae-451f7c966e13', '291fb648-cb52-563e-9199-f6ef1b84ec28', NULL, 'Артём Ж.', 'FAMILY', 8.0, '2025-10-01', 'Рекомендую, но с оговорками', 'Галька мелкая и чистая, море без мути даже после ветра. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха.', 'Слышимость хорошая — соседей слышно, берите беруши.', ARRAY['+пляж', '+детям', '-шум'], '2025-10-14T12:00:00+03:00');
