INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('02c5fcd2-f43a-5b7b-b801-f7eac4f66467', '291fb648-cb52-563e-9199-f6ef1b84ec28', NULL, 'Евгений Я.', 'SENIORS', 8.5, '2025-09-01', 'Рекомендую, но с оговорками', 'Галька мелкая и чистая, море без мути даже после ветра. На завтрак местная кухня — пробовали каждый день что-то новое. На ресепшене помогли с экскурсиями и такси.', 'Слышимость хорошая — соседей слышно, берите беруши.', ARRAY['+пляж', '+еда', '-шум', '+персонал'], '2025-10-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('226fcd6b-5e96-58b4-809d-7bc593146361', '291fb648-cb52-563e-9199-f6ef1b84ec28', NULL, 'Алина Х.', 'FRIENDS', 6.5, '2025-08-01', 'На один раз', 'Галька мелкая и чистая, море без мути даже после ветра. Завтраки вкусные, кофе нормальный, а не из автомата. Номер убирали каждый день, бельё меняли без напоминаний.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. В жару вода у берега «зацвела», плавали в бассейне. Слышимость хорошая — соседей слышно, берите беруши.', ARRAY['+пляж', '-толпы', '-цветение воды', '+еда', '+чистота', '-шум'], '2025-09-10T12:00:00+03:00');
