INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4f47d0dd-5dce-5ff8-a6ba-14df121659f6', '306115ad-e752-5618-9aec-333a772e2d03', NULL, 'Арман Р.', 'COUPLE', 8.5, '2026-04-01', 'Хороший отдых', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Взяли маски — у камней полно рыбы. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Тихо, ночью ничего не слышно — отлично выспались. Персонал приветливый, любые вопросы решали быстро.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '+снорклинг', '+еда', '-уборка', '+тишина', '+персонал'], '2026-05-07T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9e1605b5-3b75-5c7a-9bf5-351179991973', '306115ad-e752-5618-9aec-333a772e2d03', NULL, 'Айгерим Д.', 'FAMILY', 8.5, '2026-04-01', 'Хороший отдых', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Хорошая шумоизоляция, спали с открытым балконом. На ресепшене помогли с экскурсиями и такси.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '+детям', '-уборка', '+тишина', '+персонал'], '2026-05-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6924f0dd-4c2d-5306-bf22-bbfcbb98ca06', '306115ad-e752-5618-9aec-333a772e2d03', NULL, 'Юлия У.', 'COUPLE', 8.0, '2025-01-01', 'Достойно за свои деньги', 'Песок мягкий, вода прозрачная, к морю пара минут. Персонал приветливый, любые вопросы решали быстро.', 'Цены в баре и ресторане кусаются.', ARRAY['+пляж', '-цены', '+персонал'], '2025-02-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a75be768-d0f1-5eff-b4d4-61573b224ef7', '306115ad-e752-5618-9aec-333a772e2d03', NULL, 'Константин Ш.', 'COUPLE', 8.5, '2026-04-01', 'Хороший отдых', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. На ресепшене помогли с экскурсиями и такси.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '+снорклинг', '-уборка', '+персонал'], '2026-05-10T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('761cb32a-2bc5-577c-a957-66b34cc337ba', '306115ad-e752-5618-9aec-333a772e2d03', NULL, 'Дарья С.', 'SENIORS', 7.0, '2025-12-01', 'Ожидали большего', 'Бикини-бич Маафуши рядом — песок чистый, лежаки бесплатные. Взяли маски — у камней полно рыбы. Очень спокойно, слышно только птиц и море.', 'Пыль под кроватью и на балконе, пришлось просить убрать. Лифта нет — с чемоданами и пожилыми родителями тяжело.', ARRAY['+пляж', '+снорклинг', '-уборка', '+тишина', '-нет лифта'], '2025-12-19T12:00:00+03:00');
