INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9b4596d0-b86a-5131-9271-c9d9dfff897a', '3b201dbb-3e8a-5c8c-aa92-e257ba196074', NULL, 'Евгений Ж.', 'COUPLE', 9.0, '2026-07-01', 'Вернёмся ещё!', 'Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями.', NULL, ARRAY['+тишина', '+расположение'], '2026-07-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5118e70f-a4d5-5618-b794-6cd5fe034c2d', '3b201dbb-3e8a-5c8c-aa92-e257ba196074', NULL, 'Константин С.', 'BUSINESS', 8.5, '2025-10-01', 'Хороший отдых', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Тихо, ночью ничего не слышно — отлично выспались. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+еда', '+тишина', '+Wi-Fi', '+расположение', '-ремонт'], '2025-11-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5874d5b1-c2ad-5a2d-a2ef-fa83a900317a', '3b201dbb-3e8a-5c8c-aa92-e257ba196074', NULL, 'Тимур Л.', 'BUSINESS', 8.5, '2026-02-01', 'Рекомендую, но с оговорками', 'Завтраки вкусные, кофе нормальный, а не из автомата. Очень спокойно, слышно только птиц и море. Wi-Fi быстрый, без проблем работал из номера. Расположение супер: всё главное — пешком.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+еда', '+тишина', '+Wi-Fi', '+расположение', '-рельеф'], '2026-03-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('90e22c9a-18ad-5864-9843-b0508bbd8b96', '3d3811ed-a897-5d51-b10c-dc3dfda7df13', NULL, 'Ксения Г.', 'FAMILY', 7.5, '2025-10-01', 'Рекомендую, но с оговорками', 'Море прозрачное, как в бассейне. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Аквапарк — восторг детей, горки работают с утра до вечера. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+аквапарк', '-Wi-Fi', '+персонал'], '2025-10-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('cb2f50de-cf48-52a1-a552-69397517ff3b', '3d3811ed-a897-5d51-b10c-dc3dfda7df13', NULL, 'Андрей Т.', 'COUPLE', 7.5, '2025-05-01', 'В целом всё отлично', 'Море прозрачное, как в бассейне. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Персонал приветливый, любые вопросы решали быстро.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '-рельеф', '+персонал'], '2025-05-29T12:00:00+03:00');
