INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7d392ee8-b3b8-57c1-a4c1-a76ea8362ce2', '3d3811ed-a897-5d51-b10c-dc3dfda7df13', NULL, 'Полина Л.', 'SENIORS', 7.0, '2025-04-01', 'Ожидали большего', 'Вода кристально чистая, на глубине видно каждый камень. Взяли маски — у камней полно рыбы. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Wi-Fi слабый, в номере почти не ловит. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+еда', '-Wi-Fi', '-рельеф', '+персонал'], '2025-05-07T12:00:00+03:00');
