INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('747a003a-9b82-532a-8fa5-c4934eeddc17', '427afded-ea24-5206-8448-75f538d52299', NULL, 'Ксения Б.', 'SENIORS', 7.0, '2025-09-01', 'Есть над чем поработать', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Чистота идеальная, придраться не к чему. Центр рядом, гуляли пешком целыми днями.', 'Ночью шумно: музыка с улицы до двух часов. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару. Лифта нет — с чемоданами и пожилыми родителями тяжело.', ARRAY['+еда', '+чистота', '-шум', '+расположение', '-рельеф', '-нет лифта'], '2025-10-07T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('2d6917e4-7391-5a2a-9a83-97cabed9b35b', '43b19838-d979-5d9f-9c8c-ae4ef538fd49', NULL, 'Полина Р.', 'SENIORS', 9.5, '2026-05-01', 'Всё понравилось', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+пляж', '+еда', '+чистота', '+тишина', '+персонал'], '2026-05-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('670d315d-fedd-5203-9db0-0769542644ab', '43b19838-d979-5d9f-9c8c-ae4ef538fd49', NULL, 'Игорь К.', 'SOLO', 8.0, '2026-08-01', 'В целом всё отлично', 'Пляж Чан Фу рядом — песок чистый, лежаки бесплатные. Завтраки вкусные, кофе нормальный, а не из автомата. Очень спокойно, слышно только птиц и море. Wi-Fi быстрый, без проблем работал из номера. На ресепшене помогли с экскурсиями и такси.', 'В разгар сезона на пляже тесно, лежаки занимают с утра.', ARRAY['+пляж', '-толпы', '+еда', '+тишина', '+Wi-Fi', '+персонал'], '2026-09-04T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('195e8c59-23ca-50ab-bed2-dcb6a2d0b92e', '43b19838-d979-5d9f-9c8c-ae4ef538fd49', NULL, 'Михаил Т.', 'COUPLE', 9.0, '2025-04-01', 'Вернёмся ещё!', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Завтраки вкусные, кофе нормальный, а не из автомата. Хорошая шумоизоляция, спали с открытым балконом.', NULL, ARRAY['+пляж', '+еда', '+тишина'], '2025-05-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('862d71e4-22bb-50a7-aac0-ff762150e48a', '43b19838-d979-5d9f-9c8c-ae4ef538fd49', NULL, 'Нурлан Ч.', 'FRIENDS', 8.5, '2026-06-01', 'Рекомендую, но с оговорками', 'Пляж Чан Фу рядом — песок чистый, лежаки бесплатные. На завтрак местная кухня — пробовали каждый день что-то новое. Очень спокойно, слышно только птиц и море.', 'Ремонт в номере местами староват.', ARRAY['+пляж', '+еда', '+тишина', '-ремонт'], '2026-06-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e0acedb2-3700-595f-b52a-d499c30b2404', '43b19838-d979-5d9f-9c8c-ae4ef538fd49', NULL, 'Олег Х.', 'COUPLE', 7.5, '2026-08-01', 'Достойно за свои деньги', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Тихо, ночью ничего не слышно — отлично выспались.', 'В разгар сезона на пляже тесно, лежаки занимают с утра.', ARRAY['+пляж', '-толпы', '+тишина'], '2026-09-06T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8892069b-a4dd-56f1-b9bf-94545c8fb7b0', '43b19838-d979-5d9f-9c8c-ae4ef538fd49', NULL, 'Арман Б.', 'FRIENDS', 8.0, '2026-05-01', 'Достойно за свои деньги', 'Песок мягкий, вода прозрачная, к морю пара минут. Номер убирали каждый день, бельё меняли без напоминаний. Очень спокойно, слышно только птиц и море.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+чистота', '+тишина', '-ремонт'], '2026-05-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8cf48716-8336-5d2f-a34c-faae5494af1b', '45a35643-b906-50b8-b7ee-d9b79688dca9', NULL, 'Олег Н.', 'BUSINESS', 9.0, '2025-11-01', 'Лучший отпуск за последние годы', 'На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. Персонал приветливый, любые вопросы решали быстро.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+еда', '+чистота', '+тишина', '-цены', '+персонал'], '2025-12-09T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('3dc58256-57ce-5e6f-a4bd-cb921094ad86', '45a35643-b906-50b8-b7ee-d9b79688dca9', NULL, 'Елена Е.', 'COUPLE', 9.0, '2025-03-01', 'Всё понравилось', 'Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались. Персонал приветливый, любые вопросы решали быстро.', 'Жара была под 40, днём из номера почти не выходили.', ARRAY['-жара', '+чистота', '+тишина', '+персонал'], '2025-04-02T12:00:00+03:00');
