INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('2b2cc44c-d5ee-5a06-8ece-2809fc37409d', '4a7c7ff3-7273-50c9-8ec1-509bde90e98d', NULL, 'Полина С.', 'COUPLE', 9.5, '2025-02-01', 'Всё понравилось', 'Песок мягкий, вода прозрачная, к морю пара минут. Везде чисто — и в номере, и у бассейна. Персонал приветливый, любые вопросы решали быстро.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-глубина', '+чистота', '+персонал'], '2025-03-01T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8067792b-c3d9-5e27-98ac-db164c9c8980', '4a7c7ff3-7273-50c9-8ec1-509bde90e98d', NULL, 'Алина Ч.', 'COUPLE', 8.5, '2025-12-01', 'Достойно за свои деньги', 'Песок мягкий, вода прозрачная, к морю пара минут. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-глубина', '+СПА', '+еда'], '2025-12-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9f0c8fa9-624e-5cc7-bccc-b46f2927582e', '4a7c7ff3-7273-50c9-8ec1-509bde90e98d', NULL, 'Евгений И.', 'COUPLE', 9.5, '2026-01-01', 'Отдых мечты', 'Песок мягкий, вода прозрачная, к морю пара минут. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Персонал приветливый, любые вопросы решали быстро.', 'Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно.', ARRAY['+пляж', '-глубина', '+еда', '+персонал'], '2026-01-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5e94bd25-01fb-5507-81b1-a31ff014d988', '4a7c7ff3-7273-50c9-8ec1-509bde90e98d', NULL, 'Ирина Г.', 'FAMILY', 9.5, '2025-03-01', 'Всё понравилось', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Номер убирали каждый день, бельё меняли без напоминаний.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '+детям', '-глубина', '+СПА', '+еда', '+чистота'], '2025-04-09T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9fe53923-8891-5dac-ab06-54e23666ea38', '4a7c7ff3-7273-50c9-8ec1-509bde90e98d', NULL, 'Николай В.', 'FAMILY', 10.0, '2025-03-01', 'Лучший отпуск за последние годы', 'Домашний риф острова-курорта рядом — песок чистый, лежаки бесплатные. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Везде чисто — и в номере, и у бассейна.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '+детям', '-глубина', '+снорклинг', '+СПА', '+еда', '+чистота'], '2025-03-25T12:00:00+03:00');
