INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fa056c4c-4d96-5adc-9be8-4ba59287f99a', '597d89d9-3feb-5fe9-8d7b-719b589f8fff', NULL, 'Роман Х.', 'FAMILY', 9.0, '2025-10-01', 'Отдых мечты', 'СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+СПА', '+еда', '+тишина', '+расположение', '-рельеф'], '2025-11-07T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e1d3bf03-ef21-5d58-b30b-01dc5f465cf9', '597d89d9-3feb-5fe9-8d7b-719b589f8fff', NULL, 'Елена У.', 'FAMILY', 8.0, '2025-10-01', 'Хороший отдых', 'СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Расположение супер: всё главное — пешком.', 'Уборка так себе: полотенца меняли через раз. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+СПА', '+еда', '-уборка', '+расположение', '-рельеф'], '2025-10-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('cd49b78a-6a5e-564a-ab95-216fa43616b6', '597d89d9-3feb-5fe9-8d7b-719b589f8fff', NULL, 'Ирина Р.', 'COUPLE', 8.5, '2026-09-01', 'Хороший отдых', 'Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Хорошая шумоизоляция, спали с открытым балконом. Центр рядом, гуляли пешком целыми днями.', NULL, ARRAY['+еда', '+тишина', '+расположение'], '2026-10-11T12:00:00+03:00');
