INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('b1e62713-c77e-51a7-81f5-39d38859112d', '5a28b3c0-d907-581a-a74d-b24408423464', NULL, 'Людмила С.', 'FAMILY', 7.5, '2026-08-01', 'Хороший отдых', 'Пляж Чолпон-Аты рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. Дорога из аэропорта долгая — около 4 ч.', ARRAY['+пляж', '+детям', '-толпы', '+еда', '+чистота', '+тишина', '-трансфер'], '2026-09-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('952d1acb-39f3-59d6-b47f-13b7381070fb', '5a28b3c0-d907-581a-a74d-b24408423464', NULL, 'Татьяна З.', 'COUPLE', 8.5, '2025-07-01', 'Хороший отдых', 'Песок мягкий, вода прозрачная, к морю пара минут. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Чистота идеальная, придраться не к чему. На ресепшене помогли с экскурсиями и такси.', 'В разгар сезона на пляже тесно, лежаки занимают с утра.', ARRAY['+пляж', '-толпы', '+еда', '+чистота', '+персонал'], '2025-07-23T12:00:00+03:00');
