INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('905a7840-2688-5fb7-83d6-0202158b9c76', '5d323953-0467-54bf-93cc-172aceb2fedd', NULL, 'Елена Р.', 'FRIENDS', 7.5, '2025-09-01', 'В целом всё отлично', 'Вода кристально чистая, на глубине видно каждый камень.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-галька', '-глубина'], '2025-09-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f656ad36-0a9d-5201-8e8f-a71ee8e23aa9', '5d323953-0467-54bf-93cc-172aceb2fedd', NULL, 'Никита Ф.', 'COUPLE', 6.0, '2026-08-01', 'Ожидали большего', 'Вода кристально чистая, на глубине видно каждый камень. Завтраки вкусные, кофе нормальный, а не из автомата. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В разгар сезона на пляже тесно, лежаки занимают с утра. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '+еда', '-уборка', '+персонал'], '2026-08-31T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a5351a4f-0203-553f-8daf-da1468528869', '5d323953-0467-54bf-93cc-172aceb2fedd', NULL, 'Андрей Н.', 'COUPLE', 6.5, '2025-08-01', 'Есть над чем поработать', 'Море прозрачное, как в бассейне.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В разгар сезона на пляже тесно, лежаки занимают с утра. Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '-уборка'], '2025-08-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5d434c31-ef3b-5d3c-a7a5-13596f517bf0', '5d323953-0467-54bf-93cc-172aceb2fedd', NULL, 'Евгений Ф.', 'COUPLE', 6.5, '2025-12-01', 'На один раз', 'Вода кристально чистая, на глубине видно каждый камень. Завтраки вкусные, кофе нормальный, а не из автомата.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '-уборка'], '2026-01-02T12:00:00+03:00');
