INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('49c2df90-d17c-5fff-96f7-72214aec843e', '5de7f348-4c9f-5315-99d4-3b846ca25e24', NULL, 'Ирина И.', 'BUSINESS', 8.5, '2026-05-01', 'Рекомендую, но с оговорками', 'Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались. Wi-Fi быстрый, без проблем работал из номера. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+чистота', '+тишина', '+Wi-Fi', '+расположение', '-цены', '+персонал'], '2026-05-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d7648cc8-0724-5b7f-806f-91ec8a1d5b44', '5de7f348-4c9f-5315-99d4-3b846ca25e24', NULL, 'Владимир В.', 'COUPLE', 8.0, '2025-05-01', 'Рекомендую, но с оговорками', 'Везде чисто — и в номере, и у бассейна. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+чистота', '+расположение', '-цены', '+персонал'], '2025-05-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a620758a-42e3-5480-95a0-6956cdaaeacf', '5de7f348-4c9f-5315-99d4-3b846ca25e24', NULL, 'Виктория Л.', 'COUPLE', 9.0, '2025-05-01', 'Отдых мечты', 'Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+чистота', '+тишина', '+расположение', '-цены', '+персонал'], '2025-06-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('588c525a-b4f8-57a5-9bdd-d088e9d7c287', '5de7f348-4c9f-5315-99d4-3b846ca25e24', NULL, 'Павел Я.', 'SENIORS', 8.5, '2025-03-01', 'Рекомендую, но с оговорками', 'Номер убирали каждый день, бельё меняли без напоминаний. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком.', 'Ремонт в номере местами староват.', ARRAY['+чистота', '+тишина', '+расположение', '-ремонт'], '2025-03-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c09c84ab-e301-5229-b3f5-e4f383ef391b', '5de7f348-4c9f-5315-99d4-3b846ca25e24', NULL, 'Максим З.', 'SENIORS', 8.0, '2026-06-01', 'Рекомендую, но с оговорками', 'На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна. Расположение супер: всё главное — пешком.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+еда', '+чистота', '+расположение', '-цены'], '2026-06-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6ff2d8b2-910b-5614-b3c5-780d7f51e4f2', '5de7f348-4c9f-5315-99d4-3b846ca25e24', NULL, 'Полина С.', 'COUPLE', 8.0, '2025-05-01', 'Достойно за свои деньги', 'Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались. Центр рядом, гуляли пешком целыми днями.', 'Цены в баре и ресторане кусаются.', ARRAY['+чистота', '+тишина', '+расположение', '-цены'], '2025-06-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8a218dac-9d0c-5116-94f7-79f593d0b227', '5f63b075-b212-569c-8515-304e39858ed5', NULL, 'Алексей Г.', 'FAMILY', 6.5, '2026-07-01', 'Есть над чем поработать', 'Пляжи Хургады рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера. Ужины вкусные, есть детское меню.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. У рифа морские ежи — без тапочек не заходите. Жара была под 40, днём из номера почти не выходили. Ночью шумно: музыка с улицы до двух часов. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '+детям', '-толпы', '-ежи', '-жара', '+аквапарк', '+еда', '-шум', '-Wi-Fi'], '2026-07-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e66fe4c6-5f0c-5e90-b2a4-1c6c6f67506d', '5f63b075-b212-569c-8515-304e39858ed5', NULL, 'Евгений И.', 'FAMILY', 8.0, '2026-09-01', 'Рекомендую, но с оговорками', 'Пляжи Хургады рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Взяли маски — у камней полно рыбы. Аквапарк — восторг детей, горки работают с утра до вечера. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'У рифа морские ежи — без тапочек не заходите. Ночью шумно: музыка с улицы до двух часов. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '+детям', '+снорклинг', '-ежи', '+аквапарк', '+СПА', '+еда', '-шум', '-Wi-Fi'], '2026-09-30T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4d37429d-5dd0-50b9-b5c0-aacd0695b3d9', '5f63b075-b212-569c-8515-304e39858ed5', NULL, 'Дарья Х.', 'FAMILY', 9.5, '2025-12-01', 'Всё понравилось', 'Пляжи Хургады рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Взяли маски — у камней полно рыбы. Аквапарк — восторг детей, горки работают с утра до вечера. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Персонал приветливый, любые вопросы решали быстро.', 'Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '+детям', '+снорклинг', '+аквапарк', '+СПА', '+еда', '-шум', '+персонал'], '2026-01-01T12:00:00+03:00');
