INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1ea823ad-c0cf-5f80-9bc1-dfdd49ee86d9', '66f9e969-666c-5772-bee1-e9c208e5165b', NULL, 'Ксения З.', 'FAMILY', 9.0, '2025-05-01', 'Вернёмся ещё!', 'Песок мягкий, вода прозрачная, к морю пара минут. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Аквапарк — восторг детей, горки работают с утра до вечера. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Везде чисто — и в номере, и у бассейна.', NULL, ARRAY['+пляж', '+детям', '+аквапарк', '+еда', '+чистота'], '2025-05-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('77487aa5-bdcf-5173-88df-00152064820c', '66f9e969-666c-5772-bee1-e9c208e5165b', NULL, 'Максим Ш.', 'FRIENDS', 8.5, '2026-04-01', 'Достойно за свои деньги', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '+СПА', '+еда', '-цены'], '2026-04-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ceb7fe87-f3cb-5029-afb1-884f0b33f29f', '66f9e969-666c-5772-bee1-e9c208e5165b', NULL, 'Дмитрий У.', 'SENIORS', 9.0, '2026-07-01', 'Лучший отпуск за последние годы', 'Песок мягкий, вода прозрачная, к морю пара минут. Везде чисто — и в номере, и у бассейна. Ездили с мамой на коляске: пандусы, лифт, в номере поручни и душ без поддона. Персонал приветливый, любые вопросы решали быстро.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '+чистота', '+доступность', '-цены', '+персонал'], '2026-07-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8a14a453-08db-5b5e-9c7f-6acd7ebc8a1a', '6bc798a3-3b8a-5172-92b3-9378470e9479', NULL, 'Игорь Х.', 'SOLO', 8.5, '2026-06-01', 'Рекомендую, но с оговорками', 'СПА отличное, массаж — лучший за поездку. Номер убирали каждый день, бельё меняли без напоминаний.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+СПА', '+чистота', '-рельеф'], '2026-06-23T12:00:00+03:00');
