INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('3bc0e981-9529-5d89-9b38-d5df7ef81e18', '6cbdc42a-a220-5358-9eda-4112da55ab29', NULL, 'Ирина Р.', 'COUPLE', 8.0, '2026-08-01', 'В целом всё отлично', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['+еда', '-уборка', '+тишина', '+расположение', '+персонал'], '2026-09-16T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5113fa76-ad53-5500-bfa9-7a66bedf489b', '6cbdc42a-a220-5358-9eda-4112da55ab29', NULL, 'Анна Ч.', 'SOLO', 7.0, '2025-10-01', 'Есть над чем поработать', 'На завтрак местная кухня — пробовали каждый день что-то новое. Центр рядом, гуляли пешком целыми днями.', 'Уборка так себе: полотенца меняли через раз. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару. Дорога из аэропорта долгая — около 5 ч.', ARRAY['+еда', '-уборка', '+расположение', '-рельеф', '-трансфер'], '2025-10-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f94dbfbd-8b53-5873-8b8e-73353d69b4db', '6cbdc42a-a220-5358-9eda-4112da55ab29', NULL, 'Андрей К.', 'BUSINESS', 8.0, '2025-10-01', 'Рекомендую, но с оговорками', 'Завтраки вкусные, кофе нормальный, а не из автомата. Хорошая шумоизоляция, спали с открытым балконом. Центр рядом, гуляли пешком целыми днями.', 'Пыль под кроватью и на балконе, пришлось просить убрать. Дорога из аэропорта долгая — около 5 ч.', ARRAY['+еда', '-уборка', '+тишина', '+расположение', '-трансфер'], '2025-11-04T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f222ea5a-9885-58a7-8eff-c574d73a6ad0', '6d4c69d0-8cc0-54f3-849c-497dfb92a641', NULL, 'Полина М.', 'FRIENDS', 7.0, '2026-07-01', 'Ожидали большего', 'Мелкая галька, вода прозрачная — видно дно. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Очень спокойно, слышно только птиц и море. Персонал приветливый, любые вопросы решали быстро.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. В июле у берега было много медуз, пару дней купались только в бассейне. Вода холоднее, чем ждали: зашёл — и сразу обратно. Дорога из аэропорта долгая — около 1 ч.', ARRAY['+пляж', '-толпы', '-медузы', '-холодная вода', '+еда', '+тишина', '-трансфер', '+персонал'], '2026-07-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fc7e79d1-ae14-5844-849c-e2f339bcff28', '6d4c69d0-8cc0-54f3-849c-497dfb92a641', NULL, 'Иван Ф.', 'SOLO', 9.0, '2026-05-01', 'Всё понравилось', 'Галька мелкая и чистая, море без мути даже после ветра. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Очень спокойно, слышно только птиц и море. Wi-Fi быстрый, без проблем работал из номера. Персонал приветливый, любые вопросы решали быстро.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '+еда', '+тишина', '+Wi-Fi', '-цены', '+персонал'], '2026-05-25T12:00:00+03:00');
