INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('54f3690a-5299-5e11-8c2f-08087a1dc839', '70d41e7b-b4aa-52b7-b559-6b6c67e20596', NULL, 'Ксения З.', 'SOLO', 8.5, '2026-06-01', 'Достойно за свои деньги', 'Мелкая галька, вода прозрачная — видно дно. Взяли маски — у камней полно рыбы. Wi-Fi быстрый, без проблем работал из номера. Персонал приветливый, любые вопросы решали быстро.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару. Дорога из аэропорта долгая — около 1 ч.', ARRAY['+пляж', '-глубина', '+снорклинг', '+Wi-Fi', '-рельеф', '-трансфер', '+персонал'], '2026-06-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('97d80f19-9230-5c2e-a939-5e58f8d1fba0', '70d41e7b-b4aa-52b7-b559-6b6c67e20596', NULL, 'Владимир З.', 'SOLO', 8.5, '2026-03-01', 'Хороший отдых', 'Мелкая галька, вода прозрачная — видно дно. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. На завтрак местная кухня — пробовали каждый день что-то новое. Чистота идеальная, придраться не к чему. Wi-Fi быстрый, без проблем работал из номера.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Дорога из аэропорта долгая — около 1 ч.', ARRAY['+пляж', '-глубина', '+снорклинг', '+еда', '+чистота', '+Wi-Fi', '-трансфер'], '2026-03-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('471bd5c7-7cc2-5adb-8ae6-db247fbdfc04', '70d41e7b-b4aa-52b7-b559-6b6c67e20596', NULL, 'Михаил Ф.', 'SENIORS', 8.0, '2025-08-01', 'Хороший отдых', 'Галька мелкая и чистая, море без мути даже после ветра. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Номер убирали каждый день, бельё меняли без напоминаний. На ресепшене помогли с экскурсиями и такси.', 'Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В августе у берега было много медуз, пару дней купались только в бассейне. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару. Дорога из аэропорта долгая — около 1 ч.', ARRAY['+пляж', '-глубина', '+снорклинг', '-медузы', '+чистота', '-рельеф', '-трансфер', '+персонал'], '2025-08-23T12:00:00+03:00');
