INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5510d50a-2076-56cc-a332-10ac73f94006', '71acb110-3598-5ff4-b068-b9fa9f0baaab', NULL, 'Дмитрий Ч.', 'COUPLE', 8.0, '2025-08-01', 'Рекомендую, но с оговорками', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями.', 'Дорога из аэропорта долгая — около 2 ч.', ARRAY['+еда', '+тишина', '+расположение', '-трансфер'], '2025-08-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6dc8fa22-c0f1-5196-9774-ecfbda26eba0', '71acb110-3598-5ff4-b068-b9fa9f0baaab', NULL, 'Константин В.', 'FRIENDS', 8.5, '2026-07-01', 'В целом всё отлично', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Чистота идеальная, придраться не к чему. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару. Дорога из аэропорта долгая — около 2 ч.', ARRAY['+еда', '+чистота', '+расположение', '-рельеф', '-трансфер', '+персонал'], '2026-07-31T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8e40f907-c935-5526-a6be-e4c5738c8f9d', '71acb110-3598-5ff4-b068-b9fa9f0baaab', NULL, 'Галина О.', 'FAMILY', 9.5, '2026-09-01', 'Отдых мечты', 'СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна. Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+СПА', '+еда', '+чистота', '+тишина', '+расположение', '-рельеф', '+персонал'], '2026-09-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c24aba81-6b69-52c4-9dcc-36549bad7180', '71acb110-3598-5ff4-b068-b9fa9f0baaab', NULL, 'Мария С.', 'SENIORS', 8.0, '2025-09-01', 'Хороший отдых', 'На завтрак местная кухня — пробовали каждый день что-то новое. Чистота идеальная, придраться не к чему. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+еда', '+чистота', '+тишина', '+расположение', '-рельеф'], '2025-09-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8f55b654-b395-58c1-bc62-44bbcd7665bf', '753aecc9-0af6-5ee8-8b3e-0d5453aca3ba', NULL, 'Роман Н.', 'COUPLE', 8.5, '2026-07-01', 'Хороший отдых', 'Везде чисто — и в номере, и у бассейна. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком.', 'Ремонт в номере местами староват.', ARRAY['+чистота', '+тишина', '+расположение', '-ремонт'], '2026-08-15T12:00:00+03:00');
