INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('779243ed-2170-53a6-b467-a925c87da611', '769cbbc9-1ae7-5582-a163-956d0f26b74f', NULL, 'Айгерим Х.', 'COUPLE', 8.5, '2026-08-01', 'Рекомендую, но с оговорками', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. На завтрак местная кухня — пробовали каждый день что-то новое. Чистота идеальная, придраться не к чему.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+еда', '+чистота', '-ремонт'], '2026-08-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6ba02f2d-1355-5af1-98e6-77a22d997ed0', '7764308b-1882-5c02-b676-31e77a59b99b', NULL, 'Игорь Р.', 'FRIENDS', 5.5, '2025-08-01', 'На один раз', 'Вода кристально чистая, на глубине видно каждый камень. Завтраки вкусные, кофе нормальный, а не из автомата. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В разгар сезона на пляже тесно, лежаки занимают с утра. В августе у берега было много медуз, пару дней купались только в бассейне. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '-медузы', '+еда', '-шум', '+персонал'], '2025-08-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e5bbb97e-c64b-5ab2-9d09-cb0b11ada7e9', '7764308b-1882-5c02-b676-31e77a59b99b', NULL, 'Анна П.', 'COUPLE', 5.5, '2025-07-01', 'На один раз', 'Море прозрачное, как в бассейне.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В разгар сезона на пляже тесно, лежаки занимают с утра. В жару вода у берега «зацвела», плавали в бассейне. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '-цветение воды', '-шум'], '2025-07-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('71ed39c3-ced6-5387-acc8-1c6adeff8dcf', '7764308b-1882-5c02-b676-31e77a59b99b', NULL, 'Максим У.', 'COUPLE', 5.5, '2025-04-01', 'На один раз', 'Море прозрачное, как в бассейне. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Слышимость хорошая — соседей слышно, берите беруши. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '-шум', '-рельеф', '+персонал'], '2025-05-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('78021b72-0b79-5a88-8757-3992e6201647', '7764308b-1882-5c02-b676-31e77a59b99b', NULL, 'Юлия М.', 'SOLO', 6.5, '2026-07-01', 'На один раз', 'Море прозрачное, как в бассейне. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В разгар сезона на пляже тесно, лежаки занимают с утра. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '+еда', '-шум'], '2026-07-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('05adbd01-bff9-53fe-86de-b23c45f5d687', '787d9978-e93d-57fd-a799-1196bdfa0307', NULL, 'Нурлан В.', 'SENIORS', 9.0, '2025-09-01', 'Вернёмся ещё!', 'Мелкая галька, вода прозрачная — видно дно. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Хорошая шумоизоляция, спали с открытым балконом. Ездили с мамой на коляске: пандусы, лифт, в номере поручни и душ без поддона. На ресепшене помогли с экскурсиями и такси.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Смотрите таблицу приливов! В отлив по колено на сотню метров, плавать нельзя.', ARRAY['+пляж', '-глубина', '-отливы', '+снорклинг', '+СПА', '+еда', '+тишина', '+доступность', '+персонал'], '2025-09-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('3fb400ca-c65a-55c1-8a30-5d868818a72d', '787d9978-e93d-57fd-a799-1196bdfa0307', NULL, 'Ксения К.', 'COUPLE', 7.5, '2026-05-01', 'В целом всё отлично', 'Галька мелкая и чистая, море без мути даже после ветра.', 'Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Отливы сильные: после обеда вода уходит далеко, купались только в прилив.', ARRAY['+пляж', '-глубина', '-отливы'], '2026-05-30T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e6e2a6e6-6377-5bf3-8a1e-d0624e8a0a44', '787d9978-e93d-57fd-a799-1196bdfa0307', NULL, 'Ксения Е.', 'FAMILY', 9.0, '2025-12-01', 'Лучший отпуск за последние годы', 'Галька мелкая и чистая, море без мути даже после ветра. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Аквапарк — восторг детей, горки работают с утра до вечера. Детский клуб с аниматорами — удалось и самим отдохнуть.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Отливы сильные: после обеда вода уходит далеко, с ребёнком купались только утром.', ARRAY['+пляж', '-глубина', '-отливы', '+снорклинг', '+аквапарк', '+детям'], '2026-01-09T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('90033590-397f-5de4-8871-b001bdf016f1', '787d9978-e93d-57fd-a799-1196bdfa0307', NULL, 'Алексей Х.', 'COUPLE', 7.0, '2025-09-01', 'Ожидали большего', 'Мелкая галька, вода прозрачная — видно дно. СПА отличное, массаж — лучший за поездку. Тихо, ночью ничего не слышно — отлично выспались.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Отливы сильные: после обеда вода уходит далеко, купались только в прилив. У рифа морские ежи — без тапочек не заходите.', ARRAY['+пляж', '-глубина', '-отливы', '-ежи', '+СПА', '+тишина'], '2025-10-02T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f2479707-6584-5bed-b794-74060966ee58', '791fbbd1-fe2b-5c21-b452-9779085d0306', NULL, 'Анна О.', 'COUPLE', 9.0, '2026-05-01', 'Всё понравилось', 'Везде чисто — и в номере, и у бассейна. Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+чистота', '+расположение', '+персонал'], '2026-06-06T12:00:00+03:00');
