INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5eee239d-0604-5383-815a-26b00109c468', '791fbbd1-fe2b-5c21-b452-9779085d0306', NULL, 'Никита У.', 'COUPLE', 9.0, '2025-05-01', 'Отдых мечты', 'Завтраки вкусные, кофе нормальный, а не из автомата. Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком.', 'Ремонт в номере местами староват.', ARRAY['+еда', '+чистота', '+тишина', '+расположение', '-ремонт'], '2025-06-04T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('00aab239-8af7-5f5f-bd8f-b756a7d77f1e', '791fbbd1-fe2b-5c21-b452-9779085d0306', NULL, 'Галина Н.', 'SOLO', 8.5, '2026-05-01', 'Рекомендую, но с оговорками', 'Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями. На ресепшене помогли с экскурсиями и такси.', 'Дорога из аэропорта долгая — около 3 ч.', ARRAY['+чистота', '+тишина', '+Wi-Fi', '+расположение', '-трансфер', '+персонал'], '2026-05-29T12:00:00+03:00');
