INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('b8fde06b-1d1c-51ca-b628-42531611fbca', '7a4b6170-09c3-5252-b8e2-af51055b0960', NULL, 'Нурлан Х.', 'COUPLE', 8.5, '2025-03-01', 'Достойно за свои деньги', 'На завтрак местная кухня — пробовали каждый день что-то новое. Номер убирали каждый день, бельё меняли без напоминаний. Хорошая шумоизоляция, спали с открытым балконом. На ресепшене помогли с экскурсиями и такси.', 'Жара была под 40, днём из номера почти не выходили.', ARRAY['-жара', '+еда', '+чистота', '+тишина', '+персонал'], '2025-03-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e41ed57d-c14d-5f08-ad4e-fc2fefdc3125', '7a4b6170-09c3-5252-b8e2-af51055b0960', NULL, 'Павел У.', 'FAMILY', 8.0, '2026-01-01', 'Хороший отдых', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Персонал приветливый, любые вопросы решали быстро.', 'Ремонт в номере местами староват.', ARRAY['+еда', '-ремонт', '+персонал'], '2026-01-26T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4348ad46-7330-570c-9a38-f9f25615d5a2', '7a4b6170-09c3-5252-b8e2-af51055b0960', NULL, 'Наталья Е.', 'FAMILY', 9.5, '2025-02-01', 'Лучший отпуск за последние годы', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море.', NULL, ARRAY['+еда', '+чистота', '+тишина'], '2025-03-12T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4fe76aa7-bf7c-573f-ab6f-b4657085b7e9', '7a4b6170-09c3-5252-b8e2-af51055b0960', NULL, 'Константин И.', 'COUPLE', 8.5, '2026-02-01', 'В целом всё отлично', 'СПА отличное, массаж — лучший за поездку. Очень спокойно, слышно только птиц и море.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+СПА', '+тишина', '-ремонт'], '2026-02-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('79201efe-578d-5a51-995f-91b9eefaa741', '7c47a535-ae81-5c47-a635-c8018ae7cf91', NULL, 'Анна И.', 'SOLO', 7.5, '2025-05-01', 'В целом всё отлично', 'Мелкая галька, вода прозрачная — видно дно. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Номер убирали каждый день, бельё меняли без напоминаний. Персонал приветливый, любые вопросы решали быстро.', 'Wi-Fi слабый, в номере почти не ловит. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '+еда', '+чистота', '-Wi-Fi', '-рельеф', '+персонал'], '2025-06-08T12:00:00+03:00');
