INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('85c0e6d0-6431-5db4-a58b-e0ae674727c4', '7d315beb-5382-5bff-84e3-b537a053aa80', NULL, 'Светлана Х.', 'COUPLE', 8.5, '2025-10-01', 'Достойно за свои деньги', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', 'Ночью шумно: музыка с улицы до двух часов.', ARRAY['+еда', '-шум', '+расположение', '+персонал'], '2025-10-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('15be1750-82d3-56d4-812a-d1fc4c119ecf', '7d482c6e-d455-5102-9013-59300e7a8fce', NULL, 'Анна Ш.', 'FRIENDS', 6.0, '2026-08-01', 'На один раз', 'Вода кристально чистая, на глубине видно каждый камень. Ужины вкусные, есть детское меню. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В разгар сезона на пляже тесно, лежаки занимают с утра. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '+еда', '-рельеф', '+персонал'], '2026-09-04T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('836382e4-2b62-570d-9e61-4f3f4f7bb5d2', '7d482c6e-d455-5102-9013-59300e7a8fce', NULL, 'Ольга З.', 'FRIENDS', 7.0, '2025-08-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. Ужины вкусные, есть детское меню. Чистота идеальная, придраться не к чему.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В разгар сезона на пляже тесно, лежаки занимают с утра. В жару вода у берега «зацвела», плавали в бассейне.', ARRAY['+пляж', '-галька', '-глубина', '-толпы', '-цветение воды', '+еда', '+чистота'], '2025-08-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('880f1e09-24eb-589a-8fc6-4523de816758', '7d482c6e-d455-5102-9013-59300e7a8fce', NULL, 'Мария Н.', 'COUPLE', 7.5, '2026-05-01', 'Рекомендую, но с оговорками', 'Море прозрачное, как в бассейне. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Чистота идеальная, придраться не к чему.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '+чистота', '-рельеф'], '2026-05-17T12:00:00+03:00');
