INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fec36beb-61af-5019-b3d5-a0a70d0283e7', '7d482c6e-d455-5102-9013-59300e7a8fce', NULL, 'Иван Г.', 'SOLO', 6.0, '2026-09-01', 'Есть над чем поработать', 'Море прозрачное, как в бассейне. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В сентябре у берега было много медуз, пару дней купались только в бассейне. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '-медузы', '+еда', '-рельеф'], '2026-09-26T12:00:00+03:00');
