INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('20784c5f-9c64-58d5-b7ab-a739eb3a7b78', '7fd9312b-8cfe-5f73-97b9-6fe6e5f5c580', NULL, 'Айгерим Я.', 'COUPLE', 9.0, '2026-02-01', 'Вернёмся ещё!', 'СПА отличное, массаж — лучший за поездку. Чистота идеальная, придраться не к чему. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком.', 'Ремонт в номере местами староват.', ARRAY['+СПА', '+чистота', '+тишина', '+расположение', '-ремонт'], '2026-03-01T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1b3a18fa-3b23-50a8-b2b0-253d0969ec90', '7fd9312b-8cfe-5f73-97b9-6fe6e5f5c580', NULL, 'Арман Г.', 'BUSINESS', 9.5, '2025-12-01', 'Отдых мечты', 'Хорошая шумоизоляция, спали с открытым балконом. Wi-Fi быстрый, без проблем работал из номера. Расположение супер: всё главное — пешком.', NULL, ARRAY['+тишина', '+Wi-Fi', '+расположение'], '2026-01-09T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1254bfab-d4ab-51c6-bdc6-b77025cfa7f1', '7fd9312b-8cfe-5f73-97b9-6fe6e5f5c580', NULL, 'Павел В.', 'SOLO', 8.5, '2025-05-01', 'Рекомендую, но с оговорками', 'СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое. Номер убирали каждый день, бельё меняли без напоминаний. Очень спокойно, слышно только птиц и море. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями.', 'Дорога из аэропорта долгая — около 3 ч.', ARRAY['+СПА', '+еда', '+чистота', '+тишина', '+Wi-Fi', '+расположение', '-трансфер'], '2025-05-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9854865b-7391-58b5-9df6-aa5c09686f36', '806d4640-794c-59dc-9cef-98d77a83980e', NULL, 'Гоар Ж.', 'SENIORS', 8.0, '2025-07-01', 'В целом всё отлично', 'Пантай-Ченанг рядом — песок чистый, лежаки бесплатные. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Очень спокойно, слышно только птиц и море. Персонал приветливый, любые вопросы решали быстро.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-толпы', '+еда', '+тишина', '-Wi-Fi', '+персонал'], '2025-08-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('50cca6a9-51bf-54fb-bdc7-2aea131f7064', '806d4640-794c-59dc-9cef-98d77a83980e', NULL, 'Светлана И.', 'FRIENDS', 8.5, '2025-02-01', 'Достойно за свои деньги', 'Песок мягкий, вода прозрачная, к морю пара минут. Тихо, ночью ничего не слышно — отлично выспались.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+тишина', '-ремонт'], '2025-03-07T12:00:00+03:00');
