INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('32e99be7-f06e-5633-a1f4-40de7af8ad43', '81c0156c-4f35-5902-9f51-433e9f41739c', NULL, 'Алексей У.', 'COUPLE', 7.5, '2026-07-01', 'Рекомендую, но с оговорками', 'Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком.', 'Вечером комары — без репеллента никуда. Уборка так себе: полотенца меняли через раз. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['-комары', '-уборка', '+тишина', '+расположение', '-рельеф'], '2026-07-31T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1bce80f0-944a-5117-a5dd-0ea0d2083e2a', '8456da0d-e084-5737-bea6-db527a95b84a', NULL, 'Никита И.', 'SOLO', 8.0, '2026-02-01', 'Рекомендую, но с оговорками', 'Чистота идеальная, придраться не к чему. Хорошая шумоизоляция, спали с открытым балконом. Wi-Fi быстрый, без проблем работал из номера. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', 'Ремонт в номере местами староват.', ARRAY['+чистота', '+тишина', '+Wi-Fi', '+расположение', '-ремонт', '+персонал'], '2026-02-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8060fb21-39ac-5bed-b9db-1317ad365d79', '8456da0d-e084-5737-bea6-db527a95b84a', NULL, 'Полина У.', 'BUSINESS', 8.5, '2025-12-01', 'Достойно за свои деньги', 'На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+еда', '+чистота', '+Wi-Fi', '+расположение', '-ремонт'], '2026-01-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c2c481c2-dad2-50bf-82db-6d800aa78e6a', '8456da0d-e084-5737-bea6-db527a95b84a', NULL, 'Артём Х.', 'FAMILY', 8.0, '2025-11-01', 'Достойно за свои деньги', 'Завтраки вкусные, кофе нормальный, а не из автомата. Везде чисто — и в номере, и у бассейна. Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', 'Ремонт в номере местами староват.', ARRAY['+еда', '+чистота', '+расположение', '-ремонт', '+персонал'], '2025-12-01T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('072e7ddc-bec2-5110-98a2-7ccac1f88972', '8456da0d-e084-5737-bea6-db527a95b84a', NULL, 'Павел О.', 'FAMILY', 9.0, '2025-11-01', 'Отдых мечты', 'Везде чисто — и в номере, и у бассейна. Очень спокойно, слышно только птиц и море. Расположение супер: всё главное — пешком.', NULL, ARRAY['+чистота', '+тишина', '+расположение'], '2025-12-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c22e8944-3fda-52bc-870b-77aed60ccc2b', '8456da0d-e084-5737-bea6-db527a95b84a', NULL, 'Людмила З.', 'FRIENDS', 9.0, '2025-01-01', 'Отдых мечты', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Везде чисто — и в номере, и у бассейна. Расположение супер: всё главное — пешком.', NULL, ARRAY['+еда', '+чистота', '+расположение'], '2025-01-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7f75cef0-1fad-5475-b423-07c6f3b6aff9', '85205747-80c1-5224-b422-3629095871fb', NULL, 'Константин Х.', 'SOLO', 8.5, '2025-07-01', 'В целом всё отлично', 'Пляж Бай Зай (Камрань) рядом — песок чистый, лежаки бесплатные. Серф-школа у пляжа, за неделю встал на доску. СПА отличное, массаж — лучший за поездку. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+серфинг', '+СПА', '+еда', '-ремонт'], '2025-07-30T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7813ef15-a58c-5339-90f3-bb6fa2336180', '85205747-80c1-5224-b422-3629095871fb', NULL, 'Павел С.', 'COUPLE', 8.5, '2026-03-01', 'Хороший отдых', 'Песок мягкий, вода прозрачная, к морю пара минут. Серф-школа у пляжа, за неделю встал на доску. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Номер убирали каждый день, бельё меняли без напоминаний.', 'Цены в баре и ресторане кусаются.', ARRAY['+пляж', '+серфинг', '+СПА', '+еда', '+чистота', '-цены'], '2026-03-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d264753d-7395-5ef1-a61f-a577194af69e', '85205747-80c1-5224-b422-3629095871fb', NULL, 'Ляйсан П.', 'FAMILY', 8.5, '2025-12-01', 'Достойно за свои деньги', 'Песок мягкий, вода прозрачная, к морю пара минут. Аквапарк — восторг детей, горки работают с утра до вечера. Детский клуб с аниматорами — удалось и самим отдохнуть. Номер убирали каждый день, бельё меняли без напоминаний. Персонал приветливый, любые вопросы решали быстро.', 'Цены в баре и ресторане кусаются.', ARRAY['+пляж', '+аквапарк', '+детям', '+чистота', '-цены', '+персонал'], '2025-12-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('b31d7294-29b5-5b23-adba-14823320451e', '85205747-80c1-5224-b422-3629095871fb', NULL, 'Гоар Х.', 'SOLO', 9.0, '2026-05-01', 'Вернёмся ещё!', 'Песок мягкий, вода прозрачная, к морю пара минут. Серф-школа у пляжа, за неделю встал на доску. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Везде чисто — и в номере, и у бассейна.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '+серфинг', '+еда', '+чистота', '-цены'], '2026-05-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ddf71cd8-09ec-5583-b749-76cad4232d18', '893ed129-7fdf-5c24-897c-5958926d2a9c', NULL, 'Мария Б.', 'SENIORS', 7.5, '2026-04-01', 'Хороший отдых', 'Галле-Фейс рядом — песок чистый, лежаки бесплатные.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-глубина'], '2026-04-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d10e05fd-8a7b-5d3b-8885-8adac385c6d6', '893ed129-7fdf-5c24-897c-5958926d2a9c', NULL, 'Ляйсан Ч.', 'SOLO', 7.0, '2025-02-01', 'Ожидали большего', 'Галле-Фейс рядом — песок чистый, лежаки бесплатные. На завтрак местная кухня — пробовали каждый день что-то новое. Персонал приветливый, любые вопросы решали быстро.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-глубина', '+еда', '-уборка', '+персонал'], '2025-03-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d1a58ed0-78bd-57fd-a680-2c0df5008d4b', '893ed129-7fdf-5c24-897c-5958926d2a9c', NULL, 'Мария О.', 'COUPLE', 8.5, '2025-03-01', 'Хороший отдых', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. На ресепшене помогли с экскурсиями и такси.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-глубина', '+персонал'], '2025-04-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7ed8e257-1b80-501b-974f-1f2b096db2ed', '893ed129-7fdf-5c24-897c-5958926d2a9c', NULL, 'Полина Ф.', 'COUPLE', 7.0, '2025-08-01', 'Ожидали большего', 'Галле-Фейс рядом — песок чистый, лежаки бесплатные.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В разгар сезона на пляже тесно, лежаки занимают с утра.', ARRAY['+пляж', '-глубина', '-толпы'], '2025-08-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6128f3b5-854a-5091-9d15-e1dbf17222ef', '8cc31a5c-7682-5bfd-b49d-faedb0546a9d', NULL, 'Олег Б.', 'COUPLE', 7.5, '2026-06-01', 'Достойно за свои деньги', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', 'Вечером комары — без репеллента никуда. Слышимость хорошая — соседей слышно, берите беруши.', ARRAY['-комары', '+еда', '-шум', '+расположение', '+персонал'], '2026-06-21T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('adb11977-1191-5ed9-9e74-31f85830f700', '8cc31a5c-7682-5bfd-b49d-faedb0546a9d', NULL, 'Светлана Д.', 'FAMILY', 9.5, '2025-01-01', 'Отдых мечты', 'СПА отличное, массаж — лучший за поездку. Центр рядом, гуляли пешком целыми днями.', 'Ночью шумно: музыка с улицы до двух часов.', ARRAY['+СПА', '-шум', '+расположение'], '2025-02-11T12:00:00+03:00');
