INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('34d27338-6356-5e65-a055-ae67e60d2fa1', '8d41cc50-86c1-5355-a9fc-2ed1882191ab', NULL, 'Татьяна Ш.', 'FRIENDS', 8.5, '2025-10-01', 'Хороший отдых', 'Палм-Ков рядом — песок чистый, лежаки бесплатные. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи.', 'Везде таблички про крокодилов — купались только в лагуне и в бассейне.', ARRAY['+пляж', '+снорклинг', '-крокодилы'], '2025-10-20T12:00:00+03:00');
