INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('51bb1590-262a-50a0-aa20-137a4ff52215', '8d41cc50-86c1-5355-a9fc-2ed1882191ab', NULL, 'Сергей Ч.', 'SOLO', 9.5, '2026-09-01', 'Отдых мечты', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Wi-Fi быстрый, без проблем работал из номера. На ресепшене помогли с экскурсиями и такси.', 'Везде таблички про крокодилов — купались только в лагуне и в бассейне.', ARRAY['+пляж', '+снорклинг', '-крокодилы', '+Wi-Fi', '+персонал'], '2026-09-21T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a3b7c3ad-2ec6-5f19-9462-a5516c0ea434', '91db4935-b7c5-5572-96e7-383609290ab4', NULL, 'Евгений Ж.', 'SENIORS', 9.0, '2025-02-01', 'Вернёмся ещё!', 'Пляж Палаван (Сентоза) рядом — песок чистый, лежаки бесплатные. Ездили с мамой на коляске: пандусы, лифт, в номере поручни и душ без поддона. На ресепшене помогли с экскурсиями и такси.', 'Вечером комары — без репеллента никуда.', ARRAY['+пляж', '-комары', '+доступность', '+персонал'], '2025-02-16T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('762fac36-51ff-5207-b523-2756fe735c51', '91db4935-b7c5-5572-96e7-383609290ab4', NULL, 'Роман Н.', 'FAMILY', 8.5, '2025-03-01', 'Хороший отдых', 'Песок мягкий, вода прозрачная, к морю пара минут. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Аквапарк — восторг детей, горки работают с утра до вечера.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '+детям', '+аквапарк', '-уборка'], '2025-04-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9239b403-3340-5587-aae9-2d505e22d572', '91db4935-b7c5-5572-96e7-383609290ab4', NULL, 'Ляйсан Ф.', 'FAMILY', 8.0, '2026-07-01', 'В целом всё отлично', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Аквапарк — восторг детей, горки работают с утра до вечера. На завтрак местная кухня — пробовали каждый день что-то новое. На ресепшене помогли с экскурсиями и такси.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '+детям', '-толпы', '+аквапарк', '+еда', '-уборка', '+персонал'], '2026-07-10T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8bb5771c-6575-5d15-81df-61b6268e8b93', '91db4935-b7c5-5572-96e7-383609290ab4', NULL, 'Ольга Ж.', 'COUPLE', 7.5, '2025-12-01', 'Рекомендую, но с оговорками', 'Пляж Палаван (Сентоза) рядом — песок чистый, лежаки бесплатные. Персонал приветливый, любые вопросы решали быстро.', 'Вечером комары — без репеллента никуда. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-комары', '-уборка', '+персонал'], '2025-12-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fc276a19-f595-5677-8f9f-d5b292059ea3', '93290039-d37e-5fb0-a4f3-3b7bd28d6e55', NULL, 'Мария А.', 'COUPLE', 7.0, '2025-07-01', 'Есть над чем поработать', 'Пляж Джемете рядом — песок чистый, лежаки бесплатные. Персонал приветливый, любые вопросы решали быстро.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. В жару вода у берега «зацвела», плавали в бассейне. Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '-толпы', '-цветение воды', '-уборка', '+персонал'], '2025-07-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7435f9be-ec15-5afd-853f-4147679b22a9', '93290039-d37e-5fb0-a4f3-3b7bd28d6e55', NULL, 'Ляйсан Ф.', 'FAMILY', 8.0, '2026-09-01', 'В целом всё отлично', 'Песок мягкий, вода прозрачная, к морю пара минут. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера. Ужины вкусные, есть детское меню.', 'В сентябре у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '+детям', '-медузы', '+аквапарк', '+еда'], '2026-10-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e7796118-abea-5e44-b9b1-cadf1081a852', '93290039-d37e-5fb0-a4f3-3b7bd28d6e55', NULL, 'Ольга Ш.', 'COUPLE', 7.5, '2026-09-01', 'В целом всё отлично', 'Пляж Джемете рядом — песок чистый, лежаки бесплатные. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. На ресепшене помогли с экскурсиями и такси.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '+еда', '-уборка', '+персонал'], '2026-09-30T12:00:00+03:00');
