INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d0777dda-3b20-52c8-8c84-24c95190e2fd', '942d2442-cc10-5070-a5cd-71c4ebda4f2b', NULL, 'Юлия У.', 'FRIENDS', 6.0, '2025-07-01', 'Ожидали большего', 'Тёмный вулканический песок — непривычно, но очень красиво на фото.', 'В обед песок раскаляется — без сланцев не дойти до воды. В разгар сезона на пляже тесно, лежаки занимают с утра. Жара была под 40, днём из номера почти не выходили. В июле у берега было много медуз, пару дней купались только в бассейне. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-горячий песок', '-толпы', '-жара', '-медузы', '-шум'], '2025-07-21T12:00:00+03:00');
