INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d8f59e25-2786-5bff-9e8e-f82ff28f00fc', '96f72527-d3df-540c-b8a9-6f8855c86c6f', NULL, 'Юлия Ч.', 'FRIENDS', 8.5, '2025-06-01', 'Достойно за свои деньги', 'Море прозрачное, как в бассейне. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Везде чисто — и в номере, и у бассейна. Персонал приветливый, любые вопросы решали быстро.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '+чистота', '+персонал'], '2025-06-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('71e578d6-f832-5ba4-95d3-d6a4122725a1', '96f72527-d3df-540c-b8a9-6f8855c86c6f', NULL, 'Дарья Я.', 'FAMILY', 7.0, '2026-08-01', 'Ожидали большего', 'Море прозрачное, как в бассейне.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В жару вода у берега «зацвела», плавали в бассейне.', ARRAY['+пляж', '-галька', '-глубина', '-цветение воды'], '2026-08-31T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('93ce9b41-2ad3-5bc0-8532-d275ba85d266', '96f72527-d3df-540c-b8a9-6f8855c86c6f', NULL, 'Татьяна О.', 'COUPLE', 6.5, '2026-09-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. Везде чисто — и в номере, и у бассейна. Тихо, ночью ничего не слышно — отлично выспались. Персонал приветливый, любые вопросы решали быстро.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В сентябре у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-галька', '-глубина', '-медузы', '+чистота', '+тишина', '+персонал'], '2026-10-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6db53d87-9a5e-5c95-bff0-0f6bda715c12', '96f72527-d3df-540c-b8a9-6f8855c86c6f', NULL, 'Екатерина С.', 'COUPLE', 8.0, '2025-09-01', 'Достойно за свои деньги', 'Море прозрачное, как в бассейне. На завтрак местная кухня — пробовали каждый день что-то новое. Номер убирали каждый день, бельё меняли без напоминаний. Тихо, ночью ничего не слышно — отлично выспались. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '+чистота', '+тишина', '+персонал'], '2025-09-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5517b107-e3e3-5c6d-94a0-46d80b150a03', '96f72527-d3df-540c-b8a9-6f8855c86c6f', NULL, 'Роман Ж.', 'SOLO', 6.0, '2026-07-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. На завтрак местная кухня — пробовали каждый день что-то новое. Чистота идеальная, придраться не к чему.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В жару вода у берега «зацвела», плавали в бассейне. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '-цветение воды', '+еда', '+чистота', '-рельеф'], '2026-08-09T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5915e70b-5925-56f4-9ae1-b63b1bc1228e', '97137e24-531f-594f-a696-de6f93764ad4', NULL, 'Светлана Н.', 'COUPLE', 8.0, '2026-07-01', 'Достойно за свои деньги', 'Очень спокойно, слышно только птиц и море. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', NULL, ARRAY['+тишина', '+расположение', '+персонал'], '2026-07-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('014ed41c-a6d6-549f-aace-d5c764489779', '97137e24-531f-594f-a696-de6f93764ad4', NULL, 'Татьяна О.', 'SOLO', 8.5, '2025-10-01', 'Рекомендую, но с оговорками', 'Центр рядом, гуляли пешком целыми днями.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['-Wi-Fi', '+расположение'], '2025-10-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('43ee6c60-ed39-5ca7-9e6e-b2586074be05', '97137e24-531f-594f-a696-de6f93764ad4', NULL, 'Галина Д.', 'FAMILY', 9.0, '2026-02-01', 'Вернёмся ещё!', 'Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+расположение', '+персонал'], '2026-03-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('0d340cbe-e4bd-55a0-914b-329f689c0a7e', '97137e24-531f-594f-a696-de6f93764ad4', NULL, 'Галина Н.', 'SOLO', 8.0, '2025-05-01', 'В целом всё отлично', 'Тихо, ночью ничего не слышно — отлично выспались. Центр рядом, гуляли пешком целыми днями. На ресепшене помогли с экскурсиями и такси.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+тишина', '-Wi-Fi', '+расположение', '+персонал'], '2025-05-19T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('28b59aab-c12d-5efd-b94d-4363e3b15763', '9ab55d38-16ce-5b6f-ac93-10dc25e00c79', NULL, 'Анна Ж.', 'COUPLE', 9.5, '2026-04-01', 'Отдых мечты', 'Песок мягкий, вода прозрачная, к морю пара минут. Взяли маски — у камней полно рыбы. СПА отличное, массаж — лучший за поездку. Завтраки вкусные, кофе нормальный, а не из автомата. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+пляж', '+снорклинг', '+СПА', '+еда', '+персонал'], '2026-04-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('bf195a43-6d13-546a-9c27-2ed3608c9f19', '9ab55d38-16ce-5b6f-ac93-10dc25e00c79', NULL, 'Мария Я.', 'FAMILY', 7.5, '2025-11-01', 'В целом всё отлично', 'Пляж Чавенг рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Взяли маски — у камней полно рыбы. Завтраки вкусные, кофе нормальный, а не из автомата.', 'Вечером комары — без репеллента никуда.', ARRAY['+пляж', '+детям', '+снорклинг', '-комары', '+еда'], '2025-12-12T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c7488ece-bd4e-594d-b03b-52f1f5b22e0d', '9ab55d38-16ce-5b6f-ac93-10dc25e00c79', NULL, 'Светлана С.', 'COUPLE', 8.5, '2025-03-01', 'Хороший отдых', 'Пляж Чавенг рядом — песок чистый, лежаки бесплатные. Взяли маски — у камней полно рыбы. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Хорошая шумоизоляция, спали с открытым балконом. На ресепшене помогли с экскурсиями и такси.', 'Ремонт в номере местами староват.', ARRAY['+пляж', '+снорклинг', '+еда', '+тишина', '-ремонт', '+персонал'], '2025-04-09T12:00:00+03:00');
