INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('549edbd2-0f8e-560a-91de-1f0b2bb2e67e', 'a022fbae-7c1b-5e7a-8f12-f4aedaeaf72e', NULL, 'Елена А.', 'FAMILY', 5.0, '2025-08-01', 'Есть над чем поработать', 'Мелкая галька, вода прозрачная — видно дно. Ужины вкусные, есть детское меню. Персонал приветливый, любые вопросы решали быстро.', 'Жара была под 40, днём из номера почти не выходили. В августе у берега было много медуз, пару дней купались только в бассейне. Пыль под кроватью и на балконе, пришлось просить убрать. Ночью шумно: музыка с улицы до двух часов. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-жара', '-медузы', '+еда', '-уборка', '-шум', '-Wi-Fi', '+персонал'], '2025-08-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('81bf920e-3102-5323-a020-bbfa4ae20607', 'a022fbae-7c1b-5e7a-8f12-f4aedaeaf72e', NULL, 'Алина Р.', 'COUPLE', 6.5, '2026-07-01', 'Ожидали большего', 'Галька мелкая и чистая, море без мути даже после ветра. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Жара была под 40, днём из номера почти не выходили. Уборка так себе: полотенца меняли через раз. Слышимость хорошая — соседей слышно, берите беруши. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-жара', '+еда', '-уборка', '-шум', '-Wi-Fi'], '2026-07-29T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('31e3bf61-3d9f-5750-926b-7bccbf6de7bf', 'a022fbae-7c1b-5e7a-8f12-f4aedaeaf72e', NULL, 'Виктория М.', 'SOLO', 6.5, '2025-02-01', 'Ожидали большего', 'Галька мелкая и чистая, море без мути даже после ветра.', 'Уборка так себе: полотенца меняли через раз. Слышимость хорошая — соседей слышно, берите беруши. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-уборка', '-шум', '-Wi-Fi'], '2025-02-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('23d5296e-cb07-501e-882e-6fe13be92ede', 'a022fbae-7c1b-5e7a-8f12-f4aedaeaf72e', NULL, 'Екатерина Е.', 'FAMILY', 6.5, '2026-07-01', 'Ожидали большего', 'Мелкая галька, вода прозрачная — видно дно. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Жара была под 40, днём из номера почти не выходили. В июле у берега было много медуз, пару дней купались только в бассейне. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-жара', '-медузы', '+еда', '-шум'], '2026-07-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ada0f372-18dd-50e3-82e0-8d6b51027a0e', 'a022fbae-7c1b-5e7a-8f12-f4aedaeaf72e', NULL, 'Полина Д.', 'SOLO', 7.5, '2026-05-01', 'Хороший отдых', 'Галька мелкая и чистая, море без мути даже после ветра. Ужины вкусные, есть детское меню. На ресепшене помогли с экскурсиями и такси.', 'Уборка так себе: полотенца меняли через раз. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '+еда', '-уборка', '-шум', '+персонал'], '2026-06-07T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('271e024d-ca06-55b4-8d6d-1a0def906f41', 'a33b5448-6afa-5165-a921-9369f22d065a', NULL, 'Юлия В.', 'COUPLE', 9.0, '2026-05-01', 'Всё понравилось', 'СПА отличное, массаж — лучший за поездку. Центр рядом, гуляли пешком целыми днями.', NULL, ARRAY['+СПА', '+расположение'], '2026-06-12T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('2453153b-00c5-5735-847d-1f7ffdbfb2d0', 'a33b5448-6afa-5165-a921-9369f22d065a', NULL, 'Михаил Л.', 'FAMILY', 8.0, '2025-04-01', 'Рекомендую, но с оговорками', 'Центр рядом, гуляли пешком целыми днями. На ресепшене помогли с экскурсиями и такси.', 'Цены в баре и ресторане кусаются.', ARRAY['+расположение', '-цены', '+персонал'], '2025-05-07T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('bcc0e634-7757-58ce-bca2-8e5e0af26b7b', 'a33b5448-6afa-5165-a921-9369f22d065a', NULL, 'Гоар У.', 'FAMILY', 8.5, '2025-08-01', 'Рекомендую, но с оговорками', 'СПА отличное, массаж — лучший за поездку. Расположение супер: всё главное — пешком.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+СПА', '+расположение', '-ремонт'], '2025-08-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9b51ccdf-dc65-5fcf-83fc-7a0798170d5c', 'a33b5448-6afa-5165-a921-9369f22d065a', NULL, 'Татьяна Д.', 'FAMILY', 9.0, '2025-09-01', 'Всё понравилось', 'Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', NULL, ARRAY['+тишина', '+расположение', '+персонал'], '2025-10-01T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1cd31b96-bed5-5127-8a7b-d2d1c84deca0', 'a33b5448-6afa-5165-a921-9369f22d065a', NULL, 'Светлана Ш.', 'BUSINESS', 9.0, '2025-09-01', 'Отдых мечты', 'Завтраки вкусные, кофе нормальный, а не из автомата. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями.', NULL, ARRAY['+еда', '+Wi-Fi', '+расположение'], '2025-10-02T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c9479d17-5a55-50b5-8194-03d56953f269', 'a33b5448-6afa-5165-a921-9369f22d065a', NULL, 'Алексей С.', 'FRIENDS', 9.5, '2025-10-01', 'Лучший отпуск за последние годы', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+еда', '+тишина', '+расположение', '-ремонт', '+персонал'], '2025-10-19T12:00:00+03:00');
