INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9948f567-fb9e-5ed9-877f-d6e214d0ad92', 'a60610b8-c0f2-5a6a-928d-6d80e1d4f079', NULL, 'Айгерим К.', 'COUPLE', 8.0, '2025-11-01', 'Достойно за свои деньги', 'СПА отличное, массаж — лучший за поездку. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Расположение супер: всё главное — пешком.', 'Уборка так себе: полотенца меняли через раз. Слышимость хорошая — соседей слышно, берите беруши. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+СПА', '+еда', '-уборка', '-шум', '-Wi-Fi', '+расположение'], '2025-11-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('2d92bd1a-5ae3-5f32-9bd3-7e5445461b5e', 'a673e44c-7494-54d6-861b-6edfad5b8025', NULL, 'Николай Д.', 'COUPLE', 8.5, '2026-04-01', 'Хороший отдых', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие.', NULL, ARRAY['+пляж'], '2026-04-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d5ce1384-4337-5c92-9c77-1c349b5ff577', 'a673e44c-7494-54d6-861b-6edfad5b8025', NULL, 'Виктория Ч.', 'FAMILY', 8.0, '2026-09-01', 'Достойно за свои деньги', 'Пляжи Евпатории рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. На ресепшене помогли с экскурсиями и такси.', 'В сентябре у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '+детям', '-медузы', '+аквапарк', '+еда', '+персонал'], '2026-10-21T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('81a47576-90d2-5168-9ee9-5bddfd44a849', 'a673e44c-7494-54d6-861b-6edfad5b8025', NULL, 'Юлия Я.', 'COUPLE', 7.5, '2025-05-01', 'Достойно за свои деньги', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. На ресепшене помогли с экскурсиями и такси.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '-цены', '+персонал'], '2025-06-08T12:00:00+03:00');
