INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('b6280532-8511-542d-a649-119695b52c66', 'a6c5206a-7987-59d8-9a35-e2434f694705', NULL, 'Владимир Ф.', 'COUPLE', 9.0, '2025-04-01', 'Лучший отпуск за последние годы', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Взяли маски — у камней полно рыбы. Очень спокойно, слышно только птиц и море. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+пляж', '+снорклинг', '+тишина', '+персонал'], '2025-05-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5a01b6c5-d227-5e3d-8ce4-7ab50ff045c9', 'a6c5206a-7987-59d8-9a35-e2434f694705', NULL, 'Алексей М.', 'COUPLE', 8.5, '2025-11-01', 'Рекомендую, но с оговорками', 'Пляж Бай Сао рядом — песок чистый, лежаки бесплатные. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое. Очень спокойно, слышно только птиц и море.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '+снорклинг', '+СПА', '+еда', '-уборка', '+тишина'], '2025-12-03T12:00:00+03:00');
