INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('1ca240c1-689f-584a-874a-3a5264810c6f', 'aa5b0161-ab2a-5c21-bbff-44e85559f0e7', NULL, 'Нурлан К.', 'FRIENDS', 8.0, '2025-10-01', 'Рекомендую, но с оговорками', 'Везде чисто — и в номере, и у бассейна. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+чистота', '+тишина', '+расположение', '-цены'], '2025-11-08T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6afd35b1-8e72-5d3b-a13f-e8cbc8ee69ae', 'aa5b0161-ab2a-5c21-bbff-44e85559f0e7', NULL, 'Нурлан Р.', 'SENIORS', 9.0, '2025-03-01', 'Вернёмся ещё!', 'Завтраки вкусные, кофе нормальный, а не из автомата. Номер убирали каждый день, бельё меняли без напоминаний. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+еда', '+чистота', '+тишина', '+расположение', '-рельеф', '+персонал'], '2025-04-14T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fa1a8f0b-e8e7-54f8-a916-6b6b0654591d', 'aa5b0161-ab2a-5c21-bbff-44e85559f0e7', NULL, 'Юлия Н.', 'FAMILY', 9.5, '2026-07-01', 'Всё понравилось', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Тихо, ночью ничего не слышно — отлично выспались. Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+еда', '+тишина', '+расположение', '+персонал'], '2026-08-17T12:00:00+03:00');
