INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('73b24ed0-01dc-5be7-a4b3-dfbabf656c2c', 'b668832d-3eb6-5076-ac4b-9bf702445b3b', NULL, 'Наталья Г.', 'FAMILY', 9.5, '2026-02-01', 'Вернёмся ещё!', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Везде чисто — и в номере, и у бассейна.', 'Ремонт в номере местами староват.', ARRAY['+пляж', '+детям', '+аквапарк', '+СПА', '+еда', '+чистота', '-ремонт'], '2026-03-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9f3d1b76-e017-5886-835d-46b0ed5c611b', 'b668832d-3eb6-5076-ac4b-9bf702445b3b', NULL, 'Светлана С.', 'FAMILY', 8.5, '2026-09-01', 'Достойно за свои деньги', 'Пляж Белека рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера. Чистота идеальная, придраться не к чему. На ресепшене помогли с экскурсиями и такси.', 'Ремонт в номере местами староват.', ARRAY['+пляж', '+детям', '+аквапарк', '+чистота', '-ремонт', '+персонал'], '2026-10-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('4ce6aad9-3e86-50f3-87ba-c9580eff1841', 'b668832d-3eb6-5076-ac4b-9bf702445b3b', NULL, 'Андрей С.', 'SENIORS', 9.0, '2025-10-01', 'Лучший отпуск за последние годы', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Ужины вкусные, есть детское меню. Номер убирали каждый день, бельё меняли без напоминаний. Ездили с мамой на коляске: пандусы, лифт, в номере поручни и душ без поддона. На ресепшене помогли с экскурсиями и такси.', NULL, ARRAY['+пляж', '+еда', '+чистота', '+доступность', '+персонал'], '2025-11-02T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('cef64871-3a05-5e8d-8796-7d86d0024fc2', 'b6b8bec4-9c20-5f68-a8c4-6cf2580dbeb5', NULL, 'Айгерим К.', 'FAMILY', 6.5, '2026-01-01', 'Ожидали большего', 'Пляж Карон рядом — песок чистый, лежаки бесплатные. На завтрак местная кухня — пробовали каждый день что-то новое.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-глубина', '+еда', '-уборка'], '2026-02-10T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6fa91d45-5372-5475-8e94-b74c9d38ddf1', 'b6b8bec4-9c20-5f68-a8c4-6cf2580dbeb5', NULL, 'Константин Н.', 'SOLO', 6.0, '2025-08-01', 'Есть над чем поработать', 'Пляж Карон рядом — песок чистый, лежаки бесплатные. Персонал приветливый, любые вопросы решали быстро.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Несколько дней висели красные флаги, купаться не разрешали. Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '-глубина', '-волны', '-уборка', '+персонал'], '2025-08-30T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('154bca2c-4229-5fef-bb66-f184e0049a8d', 'b6b8bec4-9c20-5f68-a8c4-6cf2580dbeb5', NULL, 'Дмитрий Ш.', 'COUPLE', 7.5, '2025-02-01', 'Хороший отдых', 'Пляж Карон рядом — песок чистый, лежаки бесплатные. Серф-школа у пляжа, за неделю встал на доску. Завтраки вкусные, кофе нормальный, а не из автомата.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-глубина', '+серфинг', '+еда', '-уборка'], '2025-03-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('783156a8-77c8-5149-851c-a09386c6b1fb', 'b6b8bec4-9c20-5f68-a8c4-6cf2580dbeb5', NULL, 'Анна Ж.', 'COUPLE', 7.5, '2025-02-01', 'Хороший отдых', 'Песок мягкий, вода прозрачная, к морю пара минут. Серф-школа у пляжа, за неделю встал на доску.', 'Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-глубина', '+серфинг', '-уборка'], '2025-02-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8e4d295f-1988-5b6d-832d-6bf319188d4b', 'b89a42c6-4dbc-5e65-a6fc-65cdac58ba54', NULL, 'Сергей С.', 'COUPLE', 8.5, '2025-09-01', 'Рекомендую, но с оговорками', 'Завтраки вкусные, кофе нормальный, а не из автомата. Номер убирали каждый день, бельё меняли без напоминаний. Хорошая шумоизоляция, спали с открытым балконом. Центр рядом, гуляли пешком целыми днями.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+еда', '+чистота', '+тишина', '+расположение', '-цены'], '2025-10-06T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('b7378c58-6e94-5c63-a6ae-53e8f98fd69e', 'b89a42c6-4dbc-5e65-a6fc-65cdac58ba54', NULL, 'Дарья Н.', 'SOLO', 9.0, '2026-09-01', 'Лучший отпуск за последние годы', 'Номер убирали каждый день, бельё меняли без напоминаний. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком.', 'После прогулки по лесу сняли клеща — берите спрей и закрытую одежду.', ARRAY['-клещи', '+чистота', '+тишина', '+расположение'], '2026-10-03T12:00:00+03:00');
