INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('98e7fc12-7a4a-5e4a-88db-1abbb157e746', 'c7ab65ec-7f42-5f63-9b24-61ca3859ac3d', NULL, 'Никита Н.', 'SOLO', 8.0, '2025-12-01', 'Хороший отдых', 'Песок мягкий, вода прозрачная, к морю пара минут. Ужины вкусные, есть детское меню. На ресепшене помогли с экскурсиями и такси.', 'Пыль под кроватью и на балконе, пришлось просить убрать. Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '+еда', '-уборка', '-трансфер', '+персонал'], '2025-12-31T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('89da7be9-3246-5a40-9e22-c48e5691daf3', 'c7ab65ec-7f42-5f63-9b24-61ca3859ac3d', NULL, 'Арман А.', 'FAMILY', 8.0, '2025-01-01', 'В целом всё отлично', 'Песок мягкий, вода прозрачная, к морю пара минут. Вход в воду пологий, ребёнок часами плескался у берега. Взяли маски — у камней полно рыбы. Ужины вкусные, есть детское меню.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '+детям', '+снорклинг', '+еда', '-уборка'], '2025-02-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c74b8ca6-c613-5d80-90fb-8d4ce2aca9d0', 'c7ab65ec-7f42-5f63-9b24-61ca3859ac3d', NULL, 'Екатерина М.', 'SOLO', 8.5, '2026-03-01', 'Рекомендую, но с оговорками', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. На ресепшене помогли с экскурсиями и такси.', 'Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '+снорклинг', '-трансфер', '+персонал'], '2026-04-04T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c870dff3-f2c7-5b2e-968a-e7def0e0b162', 'c7ab65ec-7f42-5f63-9b24-61ca3859ac3d', NULL, 'Сергей М.', 'COUPLE', 8.5, '2025-02-01', 'Достойно за свои деньги', 'Бухта Унаватуна рядом — песок чистый, лежаки бесплатные. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. На ресепшене помогли с экскурсиями и такси.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+еда', '-ремонт', '+персонал'], '2025-02-25T12:00:00+03:00');
