INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('77bd848c-f013-5f47-829f-b1c4849d71d7', 'cd64bf92-65ec-5bc8-87cf-b5e20898f55d', NULL, 'Тимур О.', 'BUSINESS', 9.5, '2025-11-01', 'Отдых мечты', 'Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями. На ресепшене помогли с экскурсиями и такси.', NULL, ARRAY['+чистота', '+тишина', '+Wi-Fi', '+расположение', '+персонал'], '2025-12-08T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('3a7a4499-ccd9-590d-8d65-228ad6085943', 'cd64bf92-65ec-5bc8-87cf-b5e20898f55d', NULL, 'Анна Б.', 'BUSINESS', 8.5, '2025-07-01', 'Рекомендую, но с оговорками', 'Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море. Wi-Fi быстрый, без проблем работал из номера. Центр рядом, гуляли пешком целыми днями.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+чистота', '+тишина', '+Wi-Fi', '+расположение', '-ремонт'], '2025-07-21T12:00:00+03:00');
