INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('0b9ac276-a789-5a6b-a2e5-892044c942be', 'cd64bf92-65ec-5bc8-87cf-b5e20898f55d', NULL, 'Светлана Е.', 'COUPLE', 8.0, '2025-07-01', 'Хороший отдых', 'Везде чисто — и в номере, и у бассейна. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', 'Вечером комары — без репеллента никуда.', ARRAY['-комары', '+чистота', '+тишина', '+расположение', '+персонал'], '2025-08-09T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9f6e4332-39cd-5cc6-9e3a-9d7cc2b6b783', 'cd64bf92-65ec-5bc8-87cf-b5e20898f55d', NULL, 'Сергей Р.', 'COUPLE', 8.0, '2026-01-01', 'Рекомендую, но с оговорками', 'Везде чисто — и в номере, и у бассейна. Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями.', 'Ремонт в номере местами староват.', ARRAY['+чистота', '+тишина', '+расположение', '-ремонт'], '2026-02-14T12:00:00+03:00');
