INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('86e4c638-a360-5f14-a17c-65ac653c975c', 'cf5bc649-36fa-5d77-bf60-43486b18d995', NULL, 'Артём Я.', 'COUPLE', 8.0, '2025-08-01', 'Рекомендую, но с оговорками', 'Пляжи Евпатории рядом — песок чистый, лежаки бесплатные. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Персонал приветливый, любые вопросы решали быстро.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. В августе у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-толпы', '-медузы', '+еда', '+персонал'], '2025-08-24T12:00:00+03:00');
