INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('bc188d2e-0d44-5429-b111-185d0f1788c5', 'db6a7ad1-3230-5dbb-ac45-69fa353b42da', NULL, 'Виктория В.', 'SOLO', 6.5, '2026-05-01', 'Ожидали большего', 'Вода кристально чистая, на глубине видно каждый камень. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг'], '2026-05-21T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('301c98d8-28a2-59e6-a79f-290a757c6eaa', 'db6a7ad1-3230-5dbb-ac45-69fa353b42da', NULL, 'Олег В.', 'FAMILY', 7.0, '2025-08-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В августе у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-галька', '-глубина', '-медузы'], '2025-09-05T12:00:00+03:00');
