INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e9ffee0d-ea1f-54a0-803c-2d26990cc51a', 'e94f2c1a-8e79-56a9-bf5d-9eb0b874b79f', NULL, 'Евгений Р.', 'FAMILY', 8.5, '2025-02-01', 'Рекомендую, но с оговорками', 'Песок мягкий, вода прозрачная, к морю пара минут. Вход в воду пологий, ребёнок часами плескался у берега. Хорошая шумоизоляция, спали с открытым балконом. На ресепшене помогли с экскурсиями и такси.', NULL, ARRAY['+пляж', '+детям', '+тишина', '+персонал'], '2025-02-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('19025611-b61e-596b-83e3-009147fc37d1', 'ec54b020-cf2c-583e-93e3-98bd8936f80c', NULL, 'Екатерина Ч.', 'FRIENDS', 8.5, '2025-04-01', 'Хороший отдых', 'На завтрак местная кухня — пробовали каждый день что-то новое. Хорошая шумоизоляция, спали с открытым балконом. Расположение супер: всё главное — пешком.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+еда', '-уборка', '+тишина', '+расположение'], '2025-04-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9ae67ea1-a261-52df-957e-51ab57acda90', 'ec54b020-cf2c-583e-93e3-98bd8936f80c', NULL, 'Олег Е.', 'COUPLE', 8.5, '2025-11-01', 'Рекомендую, но с оговорками', 'Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+тишина', '+расположение', '-ремонт'], '2025-11-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('18e42a52-d4e7-5e35-a33d-7ec6af914c2f', 'ec54b020-cf2c-583e-93e3-98bd8936f80c', NULL, 'Алексей Г.', 'SOLO', 8.0, '2025-11-01', 'В целом всё отлично', 'Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['-уборка', '+тишина', '+расположение'], '2025-11-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d19c506f-e4d8-55e7-9658-9db5f9689a85', 'ec54b020-cf2c-583e-93e3-98bd8936f80c', NULL, 'Сергей П.', 'FAMILY', 9.0, '2026-09-01', 'Отдых мечты', 'Тихо, ночью ничего не слышно — отлично выспались. Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['-уборка', '+тишина', '+расположение', '+персонал'], '2026-09-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7bb60f03-54ba-5e02-8dc2-29de8e975a22', 'f4d6c10b-7e3f-5ef9-9ef9-17c688870f72', NULL, 'Галина Ш.', 'FAMILY', 8.0, '2025-12-01', 'В целом всё отлично', 'Сахл-Хашиш рядом — песок чистый, лежаки бесплатные. Взяли маски — у камней полно рыбы. Везде чисто — и в номере, и у бассейна. Персонал приветливый, любые вопросы решали быстро.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. У рифа морские ежи — без тапочек не заходите.', ARRAY['+пляж', '-глубина', '+снорклинг', '-ежи', '+чистота', '+персонал'], '2025-12-20T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('dea67a79-e9d2-555d-b3f1-19a8c21a17d5', 'f4d6c10b-7e3f-5ef9-9ef9-17c688870f72', NULL, 'Артём Я.', 'FAMILY', 7.5, '2025-11-01', 'Достойно за свои деньги', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. На ресепшене помогли с экскурсиями и такси.', 'Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. У рифа морские ежи — без тапочек не заходите.', ARRAY['+пляж', '-глубина', '-ежи', '+персонал'], '2025-11-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fb541696-d836-54d7-9843-b22b15ee7f0d', 'f4d6c10b-7e3f-5ef9-9ef9-17c688870f72', NULL, 'Людмила Л.', 'FAMILY', 9.5, '2026-01-01', 'Лучший отпуск за последние годы', 'Сахл-Хашиш рядом — песок чистый, лежаки бесплатные. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-глубина', '+снорклинг', '+СПА', '+еда', '+чистота', '+тишина'], '2026-02-14T12:00:00+03:00');
