INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d0cd2033-5a7b-5949-b1a8-2fc5fcf9b80e', 'fb94d5b0-6a9a-54bb-bf86-5619653f9ceb', NULL, 'Роман Д.', 'FAMILY', 8.0, '2026-06-01', 'Хороший отдых', 'Бродбич рядом — песок чистый, лежаки бесплатные. Вход в воду пологий, ребёнок часами плескался у берега. Аквапарк — восторг детей, горки работают с утра до вечера.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '+детям', '+аквапарк', '-уборка'], '2026-07-05T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7e192248-3532-5d4f-8dee-86847fa5d0a3', 'fb94d5b0-6a9a-54bb-bf86-5619653f9ceb', NULL, 'Игорь Л.', 'SOLO', 8.0, '2025-06-01', 'Хороший отдых', 'Бродбич рядом — песок чистый, лежаки бесплатные. СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое.', 'Несколько дней висели красные флаги, купаться не разрешали. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-волны', '+СПА', '+еда', '-уборка'], '2025-07-17T12:00:00+03:00');
