INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('2f8fe74b-c933-5d10-8d3d-62ff7ac01138', 'fe64cc52-ae09-5eaa-892f-d76fadd76b43', NULL, 'Алексей Г.', 'FRIENDS', 9.5, '2025-05-01', 'Лучший отпуск за последние годы', 'Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', NULL, ARRAY['+чистота', '+тишина', '+расположение', '+персонал'], '2025-05-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5dd7c0b6-aff1-59ad-99b0-447d4e8a2c38', 'fe64cc52-ae09-5eaa-892f-d76fadd76b43', NULL, 'Ирина Л.', 'COUPLE', 9.5, '2026-04-01', 'Всё понравилось', 'СПА отличное, массаж — лучший за поездку. Тихо, ночью ничего не слышно — отлично выспались. Расположение супер: всё главное — пешком. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+СПА', '+тишина', '+расположение', '+персонал'], '2026-04-13T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('eab1ec12-60ca-5e88-9752-9ea87ea9e9ea', 'fe64cc52-ae09-5eaa-892f-d76fadd76b43', NULL, 'Айгерим Д.', 'FAMILY', 9.0, '2025-05-01', 'Отдых мечты', 'СПА отличное, массаж — лучший за поездку. Номер убирали каждый день, бельё меняли без напоминаний. Очень спокойно, слышно только птиц и море. Расположение супер: всё главное — пешком. На ресепшене помогли с экскурсиями и такси.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+СПА', '+чистота', '+тишина', '+расположение', '-цены', '+персонал'], '2025-06-03T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d6fc7a2f-3733-5591-b6ec-c8ebe844ffaf', 'fe64cc52-ae09-5eaa-892f-d76fadd76b43', NULL, 'Татьяна В.', 'FRIENDS', 10.0, '2025-05-01', 'Всё понравилось', 'На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. Центр рядом, гуляли пешком целыми днями. На ресепшене помогли с экскурсиями и такси.', 'Цены в баре и ресторане кусаются.', ARRAY['+еда', '+чистота', '+тишина', '+расположение', '-цены', '+персонал'], '2025-05-27T12:00:00+03:00');
