INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('eafa1610-97aa-5703-b286-58d08ec63795', NULL, 'b1ca34fb-b62a-54ee-ae06-c9526df6df11', 'Ольга В.', 'COUPLE', 8.5, '2025-01-01', 'Красиво, но есть нюансы', 'Покрытие — золотистый песок. Заход в воду пологий, глубина нарастает плавно. Развлечения: лодки на острова Пхи-Пхи, каякинг в мангровых, скалолазание.', 'Отливы сильные — сверяйтесь с таблицей приливов, иначе придётся идти до воды по колено сотню метров. В высокий сезон очень людно, особенно в выходные.', ARRAY['+пляж', '+пологий вход', '-отливы', '-толпы', '+развлечения'], '2025-01-12T12:00:00+03:00');
